  -- Misty Mountains / The High Passes
  [1879071651] = {
      [1] = {
      ["NAME"] = "Cirith Imladris"; 
      ["LORE"] = "Cirith Imladris acts as the lone gateway between the Valley of Rivendell and the high passes of the Misty Mountains. Once there was fair trade along this route between the dwarf-realms of the mountains and the Elves of Rivendell, but the dwarves were driven out long ago by goblins, and many other hazards have returned to make travel up through this region difficult indeed. For the most part, the Elves keep watch over Cirith Imladris, and few pass beyond its upper reaches into the Misty Mountains."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "25.41S"; 
          ["LONG"] = "3.48W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Whitcleft"; 
      ["LORE"] = "The difficult yet unassuming pass of Whitcleft turned out to be the downfall of one of the larger dwarf-realms within the northern reaches of the Misty Mountains. Believing that the goblins to the north would resolutely struggle to find or dig secret tunnels into their well-defended mines to attack, the dwarves to the south neglected the defence of this pass.\n\nA particularly cunning goblin chieftain led a horde of his people through the pass of Whitcleft in the deep of winter, forcing them to dig their way through at a terrible cost in lives -- but using this approach he came upon the dwarves from the surface unexpectedly and trapped them underground through the long months that followed, driving most to their death through starvation or futile attempts to escape the siege.\n\nSo many goblins froze during the siege that they too were decimated by it, but Durin's Folk were never able to return to their lost stronghold."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.23S"; 
          ["LONG"] = "0.16E"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Rakhâs-bizar"; 
      ["LORE"] = "Rakhâs-bizar has never been well-travelled by the Free Peoples of Middle-earth. For time immemorial, giants have lived in the peaks and valleys to the south, and only those rare few who might call them friends, or who wish to test their mettle against a truly powerful and capricious foe might have reason to travel there. Not many of the latter return."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "27.39S"; 
          ["LONG"] = "2.60E"; 
        }; 
      }; 
      };
  };
  -- Misty Mountains / Ruins of the Misty Mountains
  [1879071652] = {
      [1] = {
      ["NAME"] = "Glóin's Camp"; 
      ["LORE"] = "Only here can the Longbeards still be found in the Misty Mountains, and only in this small lonely camp built amongst the crumbled ruins of older, far grander dwarf-holdings. The few brave dwarves who have come here face insurmountable odds in the taming of these wild peaks, however, and the task seems impossible so long as the power of Angmar continues to grow in the far North."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "24.75S"; 
          ["LONG"] = "3.99W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Hríthur's Haven"; 
      ["LORE"] = "Once this ruin led into a haven used by dwarf-hunters and scouts who roamed the Misty Mountains in their incessant battles against the goblins. Now it lies sealed and abandoned, the sturdy warriors who once manned it long ago driven from the Mountains."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "24.86S"; 
          ["LONG"] = "1.89E"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Iskeld's Look-out"; 
      ["LORE"] = "Iskeld's Look-out is one of the oldest dwarf-outposts in the northern Misty Mountains. It was built to stand guard over the source of the river Bruinen and ensure that no enemy would be able to interfere with the life-giving flow of waters down into the lands below. After the fall of the Longbeard's fortress to the south, Iskeld's Look-out was abandoned, and only wild and terrible beasts roam here now."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "21.65S"; 
          ["LONG"] = "4.47W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "The Bitter Stair"; 
      ["LORE"] = "The Bitter Stair is a treacherous switchback that leads to the gate of the dwarf-fortress of Helegrod -- once the largest of the holdings of Durin's Folk in this region of Middle-earth, until in the Second Age it was sacked by the dragon Thorog and his brood, who claimed Helegrod as his lair.\n\nSome years later, a force of dwarves led by a great hero fought their way up these stairs to the fortress. Many of their number were flung to their deaths below by the drakes which defended the approach, but in the end the hero fought his way into the fortress and did indeed slay Thorog.\n\nAlas, so many dwarves were lost in the battle that they were forced to abandon it to the dragon's brood, and they have never returned thence."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.03S"; 
          ["LONG"] = "2.15W"; 
        }; 
      }; 
      };
  };
  -- Misty Mountains / Where Giants Dwell
  [1879071653] = {
      [1] = {
      ["NAME"] = "The Lornstone"; 
      ["LORE"] = "In giantish terms, the Lornstone would likely be described as a quaint villa or summer cottage. As far as anyone else is concerned, it's a grim pile of stone with a commanding overlook of the valleys that wind below, providing an excellent vantage for its inhabitants to bowl great rocks upon whatever interlopers are foolish enough to wander this far into the Mountains."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "30.33S"; 
          ["LONG"] = "2.65E"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Greybough End"; 
      ["LORE"] = "Whatever explorer gave Greybough End its name must have been desperately homesick and thinking of greener lands and happier times. Despite the name, there is nothing whatsoever comforting about these massive granite slabs piled here like children's blocks. The fact that it serves as lair to the massive brutes who constructed it only adds to the irony of its comfortingly familiar name."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "31.36S"; 
          ["LONG"] = "3.39E"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "The Giant's Needle"; 
      ["LORE"] = "The Giant's Needle is simply a massive stone spire erected by the Giants of the Misty Mountains. No purpose has ever been found for it, nor is its construction all that remarkable given the size of its builders.\n\nWhat is perhaps most remarkable about the Giant's Spire is that none of the giants has ever gotten around to knocking it down just for fun. It is this that leads scholars to believe that it does indeed have some meaning or purpose, but even the wise cannot guess at what that might be."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "30.41S"; 
          ["LONG"] = "3.57E"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Iorbar"; 
      ["LORE"] = "Iorbar is a massive, desolate settlement within which the Giants of the Misty Mountains gather from time to time. While Iorbar is not a fortress in any true sense of the word, its sheer size and great stone structures make it a formidable redoubt, and its massive inhabitants make it even more so.\n\nEven at the height of their strength within the Misty Mountains, Durin's Folk never made open war against the giants, nor attempted to drive them from Iorbar despite the occasional raids and harrasment of travellers; instead, an uneasy truce reigned for many long years until the dwarves were finally driven out of the mountains by goblins."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "29.78S"; 
          ["LONG"] = "4.24E"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Gabilazan"; 
      ["LORE"] = "Gabilazan was one of two fortresses built by Durin's Folk in the northern reaches of the Misty Mountains, beneath which stretched extensive mines. Alas, these settlements were always challenged by the goblins which infested the range. After the fall of Helegrod to the north to a maurauding Dragon and its spawn, Gabilazan was eventually isolated, besieged and overrun by goblins during the waning rule of the Longbeards.\n\nThese days the goblins have abandoned the fortress to ruin and in their stead an odd alliance of giants and the traitorous Dourhands have made it their home."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "27.90S"; 
          ["LONG"] = "0.26E"; 
        }; 
      }; 
      };
  };
  -- Trollshaws / The Road to Rivendell
  [1879071654] = {
      [1] = {
      ["NAME"] = "The Last Bridge"; 
      ["LORE"] = "Beyond this bridge the domain of Men ends. While the Lone-lands have long been left desolate and rarely-travelled, the lands beyond are altogether wild and untamed. Only the well-seasoned wanderer or skilled adventurer would brave the Trollshaws alone."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "33.47S"; 
          ["LONG"] = "23.34W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Barachen's Camp"; 
      ["LORE"] = "At the behest of the sons of Elrond, Barachen the Elf established a small camp in the southern Trollshaws from which to watch for threats on the road to Rivendell. The Elves Alphlanc and Rochwen, bound to him by friendship rather than command, assist Barachen with his duties and work to keep the road free from danger."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "34.06S"; 
          ["LONG"] = "20.20W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "The Ford of Bruinen"; 
      ["LORE"] = "This is the only crossing of the River Bruinen until it joins with the mighty Greyflood far to the south and west. The waters seem calm and placid here, but the signs along either bank suggest that the river overflows its course with great violence from time to time."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "33.50S"; 
          ["LONG"] = "11.37W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "The Gates of Imladris"; 
      ["LORE"] = "The southern passage into Rivendell is called the Gates of Imladris and establishes a clear bastion of civilization and safety in an otherwise wild land. Nevertheless, the Elves of Rivendell guard this approach carefully, and it is not entirely safe for travellers to approach unannounced -- those who pass this way with ill intent in their hearts are rarely seen or heard from again."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "32.14S"; 
          ["LONG"] = "6.20W"; 
        }; 
      }; 
      };
  };
  -- Trollshaws / Ruins of the Trollshaws
  [1879071655] = {
      [1] = {
      ["NAME"] = "Trapdoor Lair"; 
      ["LORE"] = "Of the larger spiders in Middle-earth, it seems that some have descended from a particularly dark and evil brood. Among these creatures, it is not unheard of for them to possess a cunning intelligence and even the power to speak in the languages of Men. It is rumoured that one such creature has made this ancient ruin its lair."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "26.03S"; 
          ["LONG"] = "18.54W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Ost Thondol"; 
      ["LORE"] = "Built as an outlaying watch-tower of Nan Tornaeth to the north, Ost Thondol once stood watch over the approaches to the Ford of Bruinen."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "31.07S"; 
          ["LONG"] = "13.22W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Minas Ciliant"; 
      ["LORE"] = "A fortress was constructed in Nan Tornaeth long ago. It was built as a series of strong watchtowers in these high hills, connected by elegant spans.\n\nMinas Ciliant was the north-western corner of these towers."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "26.94S"; 
          ["LONG"] = "14.95W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Ost Chall"; 
      ["LORE"] = "Ost Chall was once the main keep of the tower fortress built into the hills of Nan Tornaeth. Now it lies in ruins like all the other remnants of the old kingdom here in the Trollshaws."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "26.99S"; 
          ["LONG"] = "13.95W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Amon Varadh"; 
      ["LORE"] = "The tower of Amon Varadh was named after the high hill upon which it was constructed, providing a commanding view of the surrounding valleys."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "27.93S"; 
          ["LONG"] = "14.92W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Ost Brandras"; 
      ["LORE"] = "This is another of the towers built upon the hills of Nan Tornaeth and combined into a fortress that once provided a commanding presence for the old kingdom here in the Trollshaws.\n\nAll of this has lain in ruin for as long as any Man can remember, and only the Elves can speak of its ancient glory."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "27.97S"; 
          ["LONG"] = "13.57W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Barad Glamgil"; 
      ["LORE"] = "Barad Glamgil overlooks the southern approach into Nan Tornaeth, as well as a dramatic waterfall which cascades into deep pools at the base of the hills below the tower."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "28.93S"; 
          ["LONG"] = "13.92W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Ost Dúrgonn"; 
      ["LORE"] = "Ost Dúrgonn was constructed by the ancient Kingdom of Arnor to stand guard over the main crossing into the Trollshaws and thus deny it to invaders from the East -- however, the greater threat proved to be from the North, and this fortress fell into misuse and eventual ruin as wars raged elsewhere."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "31.57S"; 
          ["LONG"] = "20.77W"; 
        }; 
      }; 
      };
  };
  -- Ered Luin / Scouting the Dourhands
  [1879071656] = {
      [1] = {
      ["NAME"] = "Ringdale"; 
      ["PROGRESS"] = "Discover Ringdale"; 
      ["LORE"] = "The Blue Mountains are dotted with ruins dating back to the elder days when the ancestors of the Dourhands ruled a vast kingdom, ruined when Beleriand fell. Ringdale is one such ruin."; 
      ["POINTS"] = {
