      };
      [2] = {
      ["NAME"] = "The Grimwater"; 
      ["PROGRESS"] = "Discover the Grimwater"; 
      ["LORE"] = "Thr Grimwater is a large lake south and east of Thorin's Hall. The Dourhands have built an encampment here, from where they raid merchant wains and travellers passing between Thorin's Hall and the eastern lands."; 
      ["POINTS"] = {
