      [3] = {
      ["NAME"] = "Spire of Kheledûl"; 
      ["PROGRESS"] = "Discover the Spire of Kheledûl"; 
      ["LORE"] = "This obelisk memorializes the founding of the port of Kheledûl in Thorin's time. The Dourhands have claimed the city as their last true stronghold in the Blue Mountains."; 
