  -- Ered Luin / Elf-ruins Exploration
  [1879071658] = {
      [1] = {
      ["NAME"] = "Nen Hilith"; 
      ["LORE"] = "The ruins of Nen Hilith speak of more peaceful times when the Elves dwelt by the lake and contemplated the world that was. Now, evil wolves stalk the ruins, casting a dark shadow over the beautiful memory of the place."; 
      ["POINTS"] = {
