      };
      [2] = {
      ["NAME"] = "Tham Gelair"; 
      ["LORE"] = "In the days when Tham Gelair stood whole, it was a place of celebration and ceremony for the Elves of Ered Luin. Now it is a wretched ruin, a shattered memory of better days."; 
      ["POINTS"] = {
