      };
      [3] = {
      ["NAME"] = "Limael's Vineyard"; 
      ["LORE"] = "Limael's Vineyard was once the chief source of wine-grapes for the Elves of Ered Luin, but goblins have since taken over the once-peaceful vale. Nevertheless, the Elves still harvest the grapes when they ripen, as well as the trespassing goblins."; 
      ["POINTS"] = {
