  -- Shire / The Sights of the Shire
  [1879071669] = {
      [1] = {
      ["NAME"] = "The Party Tree"; 
      ["LORE"] = "This enormous tree has long been known as a place where festive occasions can be celebrated by the Hobbits of the Shire. Standing on the outskirts of Hobbiton proper it can be seen for quite some ways, and during festivities it is often hung with dozens of bright streamers and lanterns providing a cheery atmosphere for most any event."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "29.81S"; 
          ["LONG"] = "71.48W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Methel-stage"; 
      ["LORE"] = "It is said that when old Bilbo Baggins returned from his wanderings abroad, he came back with a good deal more wealth than he had before he left.\n\nWhile rumours abound as to the source and improper nature of his riches, among the works he built within the Shire was the Methel-stage upon which hobbits of an artistic leaning are invited to perform and entertain their fellows during festive occasions.\n\nOf course, Bilbo has disappeared again recently - bringing up all the old rumours of his improper adventures and such - but many of the folk of the Shire nevertheless continue to appreciate the causes to which he put his money."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "32.60S"; 
          ["LONG"] = "69.92W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Stocktower"; 
      ["LORE"] = "The Stocktower is a curious old Arnorian ruin standing guard near the Brandywine Bridge.\n\nFew such ruins still stand in the Shire - having long ago been dismantled by industrious hobbits to construct more modern residences, but the Stocktower has become something of an icon and mischevious hobbit children have been known to frequent the ruin despite their parents' admonishments to the contrary."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "33.02S"; 
          ["LONG"] = "63.57W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "The Quarry"; 
      ["LORE"] = "For a long time, dwarves were not seen with much frequency in the Shire and bringing stone from far abroad was expensive, so the hobbits constructed their own quarry to supply the needs of builders and masons.\n\nRecently, however, better quality stone has been available from the West, so the quarry has fallen into disuse and has become infested with dangerous vermin."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "27.67S"; 
          ["LONG"] = "65.59W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Bridgefields Wall"; 
      ["LORE"] = "Bridgefields Wall is one of the few remaining signs of the ancient Kingdom of Arnor within the bounds of the Shire.\n\nFarmer Puddifoot has been threatening to pull it down for years now to build walls for his own fields, but some of the richer hobbit families of Michel Delving have prevented him from doing so in the Shire councils, demanding that the wall be preserved for historical purposes. So it stands there still."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "30.47S"; 
          ["LONG"] = "64.12W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "The Great Willow"; 
      ["LORE"] = "While not as well known as the Party Tree, the Great Willow is considered a good deal more mysterious and romantic by the younger Hobbits of the Shire.\n\nFolk tales abound of Elves travelling into the West who spend their evenings in mysterious revels beneath its boughs, and young hobbit couples often come there to declare their romantic intentions, perhaps hoping a bit of fairy magic might give them luck and bravery enough to say the words."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "33.61S"; 
          ["LONG"] = "70.41W"; 
        }; 
      }; 
      };
  };
  -- Bree-land / The Barrow-downs
  [1879071670] = {
      [1] = {
      ["NAME"] = "Northern Barrows"; 
      ["LORE"] = "The path from the Great East Road into the Barrow-downs passes through the wight-haunted Northern Barrows."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "30.32S"; 
          ["LONG"] = "56.01W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "The Dead Spire"; 
      ["LORE"] = "This stone pillar stands amidst the barrows, pointing skyward like a warning finger. Even in the heat of the day, the stone of the Dead Spire is cold and casts no shadow."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "32.09S"; 
          ["LONG"] = "55.14W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "The Dead Man's Perch"; 
      ["LORE"] = "This bluff overlooks the town of Bree. Some Bree-folk claim to have seen the Dead walking upon the ridge."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "32.17S"; 
          ["LONG"] = "53.72W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "The Great Barrow"; 
      ["LORE"] = "Othrongroth, the Great Barrow, is the oldest and deepest of the ancient barrows of the Edain, the first builders of the barrows."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "33.85S"; 
          ["LONG"] = "55.81W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Ost Gorthad"; 
      ["LORE"] = "Now fallen into decay, Ost Gorthad once stood proudly as the last bastion of the Dúnedain of Cardolan against the ravages of Angmar."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "35.76S"; 
          ["LONG"] = "53.89W"; 
        }; 
      }; 
      };
  };
  -- Bree-land / The Old Forest
  [1879071671] = {
      [1] = {
      ["NAME"] = "Bald Hill"; 
      ["LORE"] = "Bald Hill is a treeless slope which rises above the treetops of the Old Forest; nevertheless, little of the surrounding landscape can be seen from here."; 
      ["POINTS"] = {
