      };
      [2] = {
      ["NAME"] = "The Weaver's Den"; 
      ["LORE"] = "Tucked away in a dark corner of the Old Forest, this is the lair of an evil brood of monstrous spiders."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "36.83S"; 
          ["LONG"] = "57.19W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Tom Bombadil's House"; 
      ["LORE"] = "This is the lodging of the strange and powerful Tom Bombadil and his wife, the River-daughter Goldberry."; 
      ["POINTS"] = {
