      [4] = {
      ["NAME"] = "Goldberry's Spring"; 
      ["LORE"] = "This pond is favoured for its beauty by the River-daughter Goldberry, wife of the enigmatic Tom Bombadil."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "31.03S"; 
          ["LONG"] = "59.31W"; 
        }; 
