  -- Bree-land / The Ruins of Bree-land
  [1879071672] = {
      [1] = {
      ["NAME"] = "Bronwe's Folly"; 
      ["LORE"] = "Little lore remains from the days of the North Kingdom, but it is said that these ruins are all that remain of a Cardolan lord's failed attempt to hold back the wrath of Angmar."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "27.02S"; 
          ["LONG"] = "47.98W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Hillshire Ruins"; 
      ["LORE"] = "This scattered ruin is all that remained of the ancient town of Hillshire, once a sister to nearby Bree."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "27.51S"; 
          ["LONG"] = "58.62W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "The Old Greenway Fort"; 
      ["LORE"] = "In the days of the kingdom of Arnor, the Old Greenway Fort stood guard over the once-busy road leading to Fornost Erain. Now it is little more than a ruined monument to a ruined kingdom."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.97S"; 
          ["LONG"] = "53.19W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Blackwold's Roost"; 
      ["LORE"] = "Once an abode of the Men of Arnor, these ruins now house an unruly mob of outlaws calling themselves the Blackwolds."; 
      ["POINTS"] = {
