      [1] = {
        "Complete the deed 'Hendroval-slayer'";
      };
      [2] = {
        "Derrota a los hendrevail en Ered Luin - Demasiado rancios para comer y demasiado agresivos para dejarlos en paz; al menos estos pájaros desagradables son buenos blancos de práctica.";
      };
  };
  -- Ered Luin / Spider-slayer
  [1879071756] = {
      [1] = {
        "Derrota a las arañas en Ered Luin - Las arañas han merodeado durante mucho tiempo en todos los rincones oscuros de la Tierra Media, pero las de Ered Luin, al menos, tienen motivos para temerte.";
      };
  };
  -- Ered Luin / Spider-slayer (Advanced)
  [1879071757] = {
