  -- Trollshaws / Giant-slayer
  [1879071788] = {
      [1] = {
        "Derrota a los gigantes en el Bosque de los Trolls - Pocos se atreven a enfrentarse a los grandes gigantes de las Montañas, pero tú te has plantado ante ellos con valentía y los has derribado.";
      };
  };
  -- Trollshaws / Giant-slayer (Advanced)
  [1879071789] = {
      [1] = {
        "Complete the deed 'Giant-slayer'";
