  -- Trollshaws / Wolf-slayer
  [1879071794] = {
      [1] = {
        "Derrota a los lobos en el Bosque de los Trolls - Los lobos que habitan el Bosque de los Trolls están entre los más salvajes y poderosos de su estirpe. No sirven ni a los Hombres ni a los trasgos; estos lobos atacan a cualquiera lo suficientemente insensato como para aventurarse en su territorio... salvo a ti.";
      };
  };
  -- Trollshaws / Wolf-slayer (Advanced)
  [1879071795] = {
      [1] = {
        "Complete the deed 'Wolf-slayer'";
      };
      [2] = {
        "Derrota a los lobos en el Bosque de los Trolls - Los lobos que habitan el Bosque de los Trolls están entre los más salvajes y poderosos de su estirpe. No sirven ni a los Hombres ni a los trasgos; estos lobos atacan a cualquiera lo suficientemente insensato como para aventurarse en su territorio... salvo a ti.";
