  -- Misty Mountains / The Forbidding Heights
  [1879099039] = {
      [1] = {
      ["NAME"] = "Cirith Daur"; 
      ["LORE"] = "Cirith Daur was once one of the major passes that travellers used to enter the High Pass. Even at the best of times, it is torn by winds and storms and is treacherous to pass through. It often becomes completely impassable during the late seasons, blocking all access between communities on the eastern and western sides of the Misty Mountains."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.28S"; 
          ["LONG"] = "3.47E"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "The Black Crack"; 
      ["LORE"] = "This small cave in the rocks of the High Pass offers apparent shelter for travellers in times of storm, but it was long ago discovered to be a concealed entrance into the burrows of Goblin-town below, from which goblins would emerge in the dark of night to kidnap those foolish enough to make camp here.\n\nThese days the crack sees little use as few even attempt the crossing any more, and the goblins more frequently emerge through the larger gate down below as they make ominous preparations for war."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "20.31S"; 
          ["LONG"] = "5.35E"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Dómstoll"; 
      ["LORE"] = "Dómstoll -- more often called the Giant's Throne in Westron -- is a great seat of massive stones that sits above the abandoned ruins of Starkhath and offers a domineering view of the surrounding region when it is not obscured by driving snow and mist.\n\nMost of the giants left this place long ago, but rumours say that one, at least, still remains to watch over this lonely domain."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "21.95S"; 
          ["LONG"] = "8.63E"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Erforgh Cleft"; 
      ["LORE"] = "The Erforgh Cleft is a massive jumble of rocks and frozen streams left behind by some great mass of ice in ages past. Now it offers some semblance of shelter from the most brutal mountain winds to a nomadic tribe of Gauredain who have made their home here.\n\nWhether the Gauredain came here of their own accord or were directed here by the Enemy is uncertain, but their presence is troubling nonetheless."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "29.60S"; 
          ["LONG"] = "9.15E"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Writhenbores"; 
      ["LORE"] = "This complex of caves called the Writhenbores seems to be formed by a great mass of boulders, larger than even the giants could hope to lift. How they came to be this way is a mystery -- perhaps by the fall of an entire peak upon the mountainside below or some equally cataclysmic event.\n\nThe caves are oddly warmer than the wind-stripped slopes outside, possibly heated by a warm spring welling up from deep below the mountain. However, any traveller hoping to take shelter within would be strongly advised to look elsewhere, for this same warmth has drawn a large and deadly brood of worms into these caves, and to carelessly wander within is certain death."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "26.71S"; 
          ["LONG"] = "8.84E"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Starkhath"; 
      ["LORE"] = "A group of travellers who passed this way many years ago described a place where giants capriciously tossed boulders across the pass for sport and amusement.\n\nThe giants appear to be gone now -- some say they were driven away when a new Great Goblin took the throne of Goblin-town and relations between the two races became intolerable. In time, tired of being tormented by their diminutive foes, the giants left this place and moved towards Iorbar to the south-west.\n\nOnly the massive stone slabs that they once used as shelter remain, echoing with the howls of the Wargs who now prowl among them."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "20.95S"; 
          ["LONG"] = "8.02E"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Hrimbarg"; 
      ["LORE"] = "Founded before the city of Helegrod, Hrimbarg was once called 'The Crown of the Misty Mountains' by the dwarves who lived there, and they marked it as the highest dwelling of their people in all the world at that time.\n\nAlas, it fell neither to goblins nor giants nor dragons or other wickedness -- but tales say it fell to a great storm that drove down upon the High Pass and did not relent for five long years, choking the passes with vast mountains of ice, even burying Hrimbarg itself beneath a deep, featureless blanket of snow.\n\nWhen at last the storm relented and their fellows from Moria came north to relieve their brothers at Hrimbarg, not one dwarf was found alive, all having frozen or starved during the long years of isolation. It was decided thereafter that Hrimbarg should not be resettled, and it has stood empty for years beyond reckoning."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "24.45S"; 
          ["LONG"] = "6.95E"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Akûltot"; 
      ["LORE"] = "Newly built since the ascension of the new Great Goblin of Goblin-town, the camp of Akûltot is set among rock ledges and spires that overlook the approach to the main gates of Goblin-town. Historically, the goblins of the Misty Mountains have eschewed the construction of camps in the inhospitable drifts and glaring light of the High Pass, and it is unsettling that they should choose to do so now.\n\nThe only likely explanation is that they are preparing to extend their grasp beyond the mountains in some fashion, which is surely ill news to those who live in the hills and forests below."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "21.50S"; 
          ["LONG"] = "4.51E"; 
        }; 
      }; 
      };
  };
  -- Misty Mountains / Goblin-town
  [1879099040] = {
      [1] = {
      ["NAME"] = "War Steadings"; 
      ["LORE"] = "The War Steading serves as a large barracks for Goblin-town, where their soldiers and skirmishers gather and prepare for raids upon the villages to either side of the Mountains. Mostly, they descend through the passages to the east to fall upon the smaller and more weakly defended settlements of Men which border the Mirkwood, but on occasion, when their strength grows, they have been known to raid Elf-settlements on the edges of Rivendell's domain -- though these over-bold assaults generally turn out badly for the goblins, and few return."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "64.03S"; 
          ["LONG"] = "54.54E"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Thundergrot"; 
      ["LORE"] = "The Thundergrot is aptly named for the enormous booming sounds that echo through the surrounding caves and passages. This thunder is produced by massive drums carried by the Cave-trolls bred and enslaved by the goblins and employed when they raid larger settlements under cover of night."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "66.43S"; 
          ["LONG"] = "54.90E"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Slave Pens"; 
      ["LORE"] = "The stench and horror of the Slave Pens of Goblin-town are the subject of dark rumour among travellers who must brave the High Pass, for it is well-known that the goblins delight in taking such folk captive and dragging them down into the depths of the Mountains where they are pressed into cruel labour in the darkness, and few ever again see the light of day."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "64.92S"; 
          ["LONG"] = "54.84E"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Gollum's Cave"; 
      ["LORE"] = "Gollum's Cave is a dark, silent lake nestled down near the roots of the Misty Mountains, and it is said that even the goblins fear it greatly and rarely come here.\n\nThe famed hobbit-burglar Bilbo Baggins stumbled into this cave long ago, and there met the wretched creature Gollum. It is said he won his freedom through a Riddle-game, but there is rumour that he did not play fairly."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "63.58S"; 
          ["LONG"] = "55.68E"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "The Great Goblin's Den"; 
      ["LORE"] = "The throne room of Goblin-town, the Den of the Great Goblin, is not a place where most travellers wish to find themselves. Possessed of an odd and unfair sense of justice, the goblins usually bring their captives before the Great Goblin to face his judgement rather than simply imprisoning or killing them. His judgement for presumptive crimes usually involves spying or tresspassing upon the goblin's domain.\n\nUnfortunately for the hapless captives, the outcome of these encounters is fore-ordained, and the punishment for such infractions is always unpleasant -- and ultimately fatal."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "64.41S"; 
          ["LONG"] = "54.79E"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "The Deep-fires"; 
      ["LORE"] = "This sweltering cave houses the forges of Goblin-town, where cruel implements of war and torture are fashioned by over-clever smiths whose knowledge descends from ages ago when the Dark Lord taught them the arts of metalsmithy."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "69.18S"; 
          ["LONG"] = "56.27E"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Eglanúr"; 
      ["LORE"] = "The true origin of the ruins that can be found scattered in these caverns is unknown. It is clear that once the dwarves delved here and built their tunnels and mines, but this was lost and abandoned to the goblins so long ago that even among Durin's Folk there are few who remember the names of those who built it or how their story came to an end."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "66.93S"; 
          ["LONG"] = "55.47E"; 
        }; 
      }; 
      };
  };
  -- Trollshaws / The Wilds of Tâl Bruinen
  [1879099041] = {
      [1] = {
      ["NAME"] = "Cirith Ulunn"; 
      ["LORE"] = "Though worms can be found scattered in other areas of the Trollshaws, the breed here has grown particularly deadly and numerous. Indeed, the aggressive hunting instincts of these vicious beasts do a great deal to dissuade those few explorers and settlers who might otherwise take up their livelihoods in the Wilds of Tal Bruinen."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "37.63S"; 
          ["LONG"] = "11.25W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Echad Candelleth"; 
      ["LORE"] = "The ruin of Echad Candelleth is believed by scholars to have once been a centre of art and learning in the ancient kingdom of Rhudaur, before it fell beneath the corrupt sway of Angmar and was destroyed in wars with its neighbours after which even its original name was lost.\n\nNow it simply acts as a makeshift camp for those hardy souls brave enough to explore the surrounding wilds."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "37.20S"; 
          ["LONG"] = "13.97W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Eryn Singor"; 
      ["LORE"] = "Though it is a wonder to behold, travellers who allow themselves to be lulled by the natural beauty of Eryn Singor rarely emerge from its treacherous ravines.\n\nA host of deadly Wood-trolls have taken up residence within, and delight in descending upon unwary hunters and explorers and tearing them limb from limb."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "35.31S"; 
          ["LONG"] = "16.51W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Echad Gauradan"; 
      ["LORE"] = "While civilized men long ago quit these hills, a tribe of wild men have recently taken up residence here, seemingly at home amongst the dangerous beasts and natural hazards of the region.\n\nAlas, they are of a savage disposition and display an obvious hatred of those who intrude upon their territory from more civilized lands."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "38.23S"; 
          ["LONG"] = "16.16W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Torech Ullug"; 
      ["LORE"] = "It is said that there is a nesting area for the numerous worms who infest Tal Bruinen, and it would seem that you have stumbled upon it here at Torech Ullug.\n\nTake care! The mothers of nesting worms are known for their particulary vicious disposition, as well as a ravenous appetite for fresh meat to feed to their young."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "39.71S"; 
          ["LONG"] = "14.62W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Delossad"; 
      ["LORE"] = "What are these strange ruins? They seem to be of ancient Cardolan origins, but the Elves of Rivendell seem hesitant to speak of them at all. Some strange mystery surrounds them, and it may be that the only answers can be found within..."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "38.20S"; 
          ["LONG"] = "13.00W"; 
        }; 
      }; 
      };
  };
  -- Misty Mountains / Bilbo's Buttons
  [1879099095] = {
      [1] = {
      ["NAME"] = "Debris Pile"; 
      ["PROGRESS"] = "Find the stained button"; 
      ["LORE"] = "A brass button stained with something... blood perhaps?\n\nIn any case, it certainly is not a goblin-relic -- it looks more like something you would find on a hobbit's waistcoat...."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "71.28S"; 
          ["LONG"] = "55.57E"; 
        }; 
      }; 
      };
      [2] = {
        "Find the tarnished button - This odd little brass button is heavily tarnished and worse for wear - but it seems that at some point it would have set well upon a rather fine coat or jacket. How did goblins get this?";
      };
      [3] = {
      ["NAME"] = "Refuse Pile"; 
      ["PROGRESS"] = "Find the polished button"; 
      ["LORE"] = "This brass button is old and worse for wear, but it looks like some curious goblin has polished it recently. He must have carried it as a keepsake of some sort."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "66.30S"; 
          ["LONG"] = "54.83E"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Battered Chest"; 
      ["PROGRESS"] = "Find the scratched button"; 
      ["LORE"] = "How odd -- a brass waistcoat button in the depths of Goblin-town? The face of the button appears to have been heavily scratched, perhaps against a rock face at some point in the distant past."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "63.93S"; 
          ["LONG"] = "54.21E"; 
        }; 
      }; 
      };
      [5] = {
        "Find the bent button - This bit of brass finery seems out of place in the dark warrens of Goblin-town. It also seems to have been bent, perhaps in whatever incident separated it from the waistcoat it once must have secured.";
      };
      [6] = {
      ["NAME"] = "Discarded Pouch"; 
      ["PROGRESS"] = "Find the shiny button"; 
      ["LORE"] = "This brass button looks surprisingly well-kept, and you can still faintly see the etched design on it that marks it as being of Shire manufacture -- but what hobbit in his right mind would venture into the depths of Goblin-town wearing a waistcoat!?"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "63.60S"; 
          ["LONG"] = "54.70E"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Ruined Bag"; 
      ["PROGRESS"] = "Find the broken cufflink"; 
      ["LORE"] = "Interesting -- this appears to be a cufflink that might have once been in fashion among the Hobbits of the Shire, but the post has snapped, and it is of little value now."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "67.55S"; 
          ["LONG"] = "55.53E"; 
        }; 
      }; 
      };
      [8] = {
        "Find the blackened cufflink - This cufflink looks like it might have once been a rather fine piece of jewellery -- likely of hobbit-make -- but it appears to have been badly marred and blackened when some clumsy goblin dropped it into a fire pit some time ago.";
      };
  };
