  -- Shadows of Angmar / The Orcs of Urugarth
  [1879114240] = {
      [1] = {
        "Derrota a los Orcos en Urugarth - En número de decenas de miles, los orcos llevan mucho tiempo formando la columna vertebral de los ejércitos del Enemigo. Hace tiempo que perdiste la cuenta de cuántas de estas criaturas repugnantes han caído ante ti — y, aun así, su número parece inmutable.";
      };
  };
  -- Shadows of Angmar / The Orcs of Urugarth (Advanced)
  [1879114241] = {
      [1] = {
        "Complete the deed 'The Orcs of Urugarth'";
      };
      [2] = {
        "Derrota a los Orcos en Urugarth - En número de decenas de miles, los orcos llevan mucho tiempo formando la columna vertebral de los ejércitos del Enemigo. Hace tiempo que perdiste la cuenta de cuántas de estas criaturas repugnantes han caído ante ti — y, aun así, su número parece inmutable.";
      };
  };
  -- Shadows of Angmar / The Trolls of Urugarth
  [1879114242] = {
      [1] = {
        "Derrota a los Trolls en Urugarth - Los trolls de Urugarth son los más mortales que hayas encontrado. Armados con armas y armaduras de las forjas del Enemigo y poseedores de una crueldad astuta, incluso los grandes héroes han caído ante su poder.";
      };
  };
  -- Shadows of Angmar / The Trolls of Urugarth (Advanced)
  [1879114243] = {
