  -- Shadows of Angmar / Marching Orders
  [1879114246] = {
      [1] = {
        "Find pages of the Orcs' marching orders scattered throughout Urugarth and discover the plans of the Enemy.";
      };
      [2] = {
        "Obtain Marching Orders, Page 7 - This page tells of Angmar's plans for Dushkal and his host of trolls.";
      };
      [3] = {
        "Obtain Marching Orders, Page 5 - This page tells of the course of training that Lagmâs is to employ in the development of Angmar's army of Orcs.";
      };
      [4] = {
        "Obtain Marching Orders, Page 14 - This page tells of new developments with the black powder stolen from Saruman's Orcs and how it can best be used to further increase the potency of the fire-pots used by the goblins of Angmar.";
      };
      [5] = {
        "Obtain Marching Orders, Page 1 - This page outlines the hierarchy among the Uruk-captains of Angmar.";
      };
      [6] = {
        "Obtain Marching Orders, Page 9 - This page highlights the best practices for maintaining the health of a growing Warg-pack.";
      };
      [7] = {
        "Obtain Marching Orders, Page 16 - This page is a rough tally of the number of slaves under the employ of Urugarth and what tasks they are directed to fulfil.";
      };
  };
