  -- Shadows of Angmar / The Enemy's Stronghold
  [1879114551] = {
      [1] = {
      ["NAME"] = "Slave-pens"; 
      ["LORE"] = "Amid the foul waters of Carn Dûm lies the slave-pens of the Trév Duvárdain. It is here that those who have challenged the might of the Steward of Angmar are pressed into his service against their will."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "12.07N"; 
          ["LONG"] = "34.44W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Barashal's Domain"; 
      ["LORE"] = "The Gorthorog-captain Barashal commands his minions from this post within the eastern crags on the outskirts of Carn Dûm."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "13.88N"; 
          ["LONG"] = "32.64W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Fell-water Source"; 
      ["LORE"] = "The water you found in this place was a putrescent green, contaminated with the vile poisons of Carn Dûm."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "12.64N"; 
          ["LONG"] = "34.00W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Duvárdain Quarter"; 
      ["LORE"] = "While Carn Dûm has many enemies, there are those that call it ally as well. Among them are the Hillmen of the Trév Duvárdain. This alliance has granted the Trév Duvárdain a district of their own within the city."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "11.83N"; 
          ["LONG"] = "34.44W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Castle of Carn Dûm"; 
      ["LORE"] = "It is from the Castle of Carn Dûm that the Witch-king of Angmar oversaw his domain, and it is from here that Mordirith, the Steward of Angmar, does the same."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "14.00N"; 
          ["LONG"] = "33.57W"; 
        }; 
      }; 
      };
