  -- Eregion / Silent and Restless
  [1879140606] = {
      [1] = {
        "Completa misiones dentro de Eregion - Has viajado a Eregion, el antiguo hogar de los Elfos que ahora habitan en Rivendel. El pueblo de Elrond busca ocultar el paso de la Comunidad del Anillo, pero también expulsar las fuerzas de Saruman el Blanco...";
      };
