  -- Eregion / Lizard and Crawler-slayer
  [1879140617] = {
      [1] = {
        "Derrota a los lagartos y gusanos en Eregion - Has eliminado a varios de los lagartos y gusanos que infestan Eregion. Las criaturas nunca han sido numerosas, pero ahora parece que su número está creciendo constantemente, a pesar de tus esfuerzos.";
      };
  };
  -- Eregion / Lizard and Crawler-slayer (Advanced)
  [1879140618] = {
      [1] = {
        "Complete the deed 'Lizard and Crawler-slayer'";
      };
