  -- Moria / The Cliffs of Zirakzigil
  [1879146845] = {
      [1] = {
      ["NAME"] = "The Door to the Clouds"; 
      ["LORE"] = "This gateway opens up onto the face of Zirakzigil, the mighty Silvertine."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "2.82S"; 
          ["LONG"] = "110.80W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "The Broken Cleft"; 
      ["LORE"] = "A great battle took place upon the face of Cloudyhead, a battle between a Balrog and another mighty Power. The Balrog's demise broke the mountainside here."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "13.42N"; 
          ["LONG"] = "109.06W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Durin's Bane"; 
      ["LORE"] = "These are the remains of the mighty fire demon who had hidden itself in Moria in the days of yore."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "14.88N"; 
          ["LONG"] = "108.70W"; 
        }; 
      }; 
      };
  };
  -- Moria / Bulwarks of the Enemy
  [1879146846] = {
      [1] = {
      ["NAME"] = "Menem-berej"; 
      ["LORE"] = "The great pit of Menem-berej once held one of the richest lodes of mithril ever discovered in Khazad-dûm, and this enormous platform was constructed to aid the dwarves in their efforts to extract the precious metal. Though this mine was believed to be mostly played out by the time of the Fall of Khazad-dûm, the dwarves of the expedition hope to find some remaining veins to prove the value of this dangerous foray, and to draw more of their bretheren from abroad to aid them in reclaiming their ancient home."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "11.04S"; 
          ["LONG"] = "112.75W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Harâzgund"; 
      ["LORE"] = "The gateway of Harâzgund leads to the source of one of the greatest waterways in all of Khazad-dûm. It once supplied water to nearly half of all the dwarves who lived beneath these mountains, but it was broken by some unknown calamity during the long dark years after the fall of Durin. Now the water lies here unmoving, flooding the deeps in great stagnant pools."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "17.60S"; 
          ["LONG"] = "116.93W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "The Forges of Khazad-dûm"; 
      ["LORE"] = "The Forges of Khazad-dûm were without rival, greatest of all forges in the Third Age of Middle-earth. The dwarves will not rest until it has been reclaimed, for much of the priceless artistry born in that hall has been lost to the long years of Moria's abandonment."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "16.98S"; 
          ["LONG"] = "109.75W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Fil Gashan"; 
      ["LORE"] = "The Orcs of Fil Ghashan are suspiciously watchful, brooding ever on their hopeful assault against Lothlórien. They show no mercy to any who dare threaten their plans."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "17.07S"; 
          ["LONG"] = "109.58W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "The Gate of Ruin"; 
      ["LORE"] = "The Gate of Ruin opens upon the Endless Stair of Khazad-dûm, but as its name now suggests, this doorway into the stairs has been shattered and lies in ruins."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "10.20S"; 
          ["LONG"] = "103.88W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Skûmfil"; 
      ["LORE"] = "The Orc-graves in Skûmfil have bred many sickening creatures, all grown strong on the flesh of the dead, and all consumed with evil thoughts."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "13.21S"; 
          ["LONG"] = "100.41W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Dark Delvings"; 
      ["LORE"] = "The Dark Delvings should have been left forgotten, for they are haunted by ancient and fell creatures with no place in Middle-earth."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "15.85S"; 
          ["LONG"] = "97.28W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "The Sixteenth Hall"; 
      ["LORE"] = "The Sixteenth Hall is now a home to the fungal disease that poisons many Orcs and turns them to corrupted Globsnaga. Great evil brews in this hall, threatening to cover Moria in sickness and fear."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "11.07S"; 
          ["LONG"] = "101.00W"; 
        }; 
      }; 
      };
  };
  -- Moria / In the Footsteps of the Fellowship
  [1879146847] = {
      [1] = {
      ["NAME"] = "Durin's Threshold"; 
      ["LORE"] = "The threshold of the western gate of Khazad-dûm, it was here that Durin completed his legendary journey through the heart of the mountains and came once again into the light of the sun, having discovered the place that would become his people's home for ages to come."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "8.00S"; 
          ["LONG"] = "115.84W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "The Chamber of the Cross-roads"; 
      ["LORE"] = "This ancient guard room controls the passages leading up into Durin's Way, as well as the ones east, towards the Twenty-first Hall. It is now occupied by part of the dwarf-expedition to reclaim Moria from the Orcs and goblins who now hold sway."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "5.09S"; 
          ["LONG"] = "112.08W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "The Twenty-first Hall"; 
      ["LORE"] = "The Twenty-first hall is among the largest in all of Khazad-dûm, and often regarded as the most famous. In times long past a great market stood here where the Dwarves of Moria and travellers from abroad would trade in fine goods from across much of Middle-earth. Fine woods and wine and foodstuffs would be exchanged for gold and priceless gems and finely wrought pieces of smith-craft. In truth nearly anything at all could be bought or sold within this very hall, though it is hard to imagine it to look upon it now."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "21.79N"; 
          ["LONG"] = "119.16W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Chamber of Mazarbul"; 
      ["LORE"] = "It is likely that the Chamber of Mazarbul once served some great ceremonial purpose in the old days of Moria; now it remains the tomb of Balin, son of Fundin and friend to old Bilbo, who, not so many years ago, led an expedition much like the current one to retake Moria and restore it to the glories of old."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "22.85N"; 
          ["LONG"] = "119.25W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "The Bridge of Khazad-dûm"; 
      ["PROGRESS"] = "Find the Bridge of Khazad-dûm (west arch)"; 
      ["LORE"] = "The bridge of Khazad-dûm was conceived as an ancient defence designed to deter any who might seek to invade the city. The chasm it crosses is among the largest in Moria, and has been here since the city was founded thousands of years ago. Now the bridge lies in ruin, its western span jutting forlornly out over the depths of the chasm, the very stone shattered and charred by unknown forces."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "8.00S"; 
          ["LONG"] = "99.19W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "The Bridge of Khazad-dûm"; 
      ["PROGRESS"] = "Find the Bridge of Khazad-dûm (east arch)"; 
      ["LORE"] = "The Bridge of Khazad-dûm has stood over this great chasm for many a long age, but does so no more. The eastern span now reaches out like a finger pointing into the darkness beyond. It seems that whatever destroyed the bridge fell not so long ago, as flakes of rock can still be seen occasionally cracking away from the shattered tip to fall away into the chasm, and fresh arrows pepper the stonework there."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "8.00S"; 
          ["LONG"] = "98.55W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "The First Hall"; 
      ["LORE"] = "The First Hall was the original entrance to Khazad-dûm, where Durin first set foot in the caverns that would one day become the greatest city of the dwarves, and indeed the most enduring city of any people in the long history of Middle-earth, until at last it fell into ruin."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "8.00S"; 
          ["LONG"] = "96.08W"; 
        }; 
      }; 
      };
  };
