  -- Race & Social / Festival Fortunes: Oddly Familiar
  [1879184300] = {
      [1] = {
        "Recoge la Fortuna -- 1 de 50 - 'Bah, eso solo habría sido un rasguño... ¡vuelve!'";
      };
      [2] = {
        "Collect Fortune -- 2 of 50 - 'Truly, your heart holds no fear, brother.'";
      };
      [3] = {
        "Collect Fortune -- 3 of 50 - 'Dance three is the step here.'";
      };
      [4] = {
        "Collect Fortune -- 4 of 50 - 'There has been a rash of rancid pies all across the Shire.'";
      };
      [5] = {
        "Collect Fortune -- 5 of 50 - 'Did you hear that, Wanetta? Asphodel said yes!'";
      };
      [6] = {
        "Collect Fortune -- 6 of 50 - 'Tra la, tra la, tra lilly, tra la. Red with blood...where life has fled. Pretty flowers...so bright red.... La la, la lilly, la la....'";
      };
      [7] = {
        "Collect Fortune -- 7 of 50 - 'I hope the Last Prince comes soon. I'm scared!'";
      };
      [8] = {
        "Collect Fortune -- 8 of 50 - You hear: 'This is not the place. Go north.'";
      };
      [9] = {
