  -- Race & Social / Festival Fortunes: A Storyteller's Snippets
  [1879184301] = {
      [1] = {
        "Recoge la Fortuna -- 11 de 50 - '¡Muchas gracias!'";
      };
      [2] = {
        "Collect Fortune -- 12 of 50 - 'I don't know half of you half as well as I should like; and I like less than half of you half as well as you deserve.'";
      };
      [3] = {
        "Collect Fortune -- 13 of 50 - 'It is a dangerous business, going out of your door.'";
      };
      [4] = {
        "Collect Fortune -- 14 of 50 - 'You step onto the Road, and if you don't keep your feet, there is no knowing where you might be swept off to.'";
      };
      [5] = {
        "Collect Fortune -- 15 of 50 - 'What have I got in my pocket?'";
      };
      [6] = {
        "Collect Fortune -- 16 of 50 - NO ADMITTANCE EXCEPT ON PARTY BUSINESS";
      };
      [7] = {
        "Collect Fortune -- 17 of 50 - 'I have called you all together for a Purpose.'";
      };
      [8] = {
        "Collect Fortune -- 18 of 50 - 'I'll do as I choose and go as I please.'";
      };
      [9] = {
        "Collect Fortune -- 19 of 50 - 'Mr. Bilbo Baggins has gone away; as far as I know, for good.'";
      };
      [10] = {
        "Collect Fortune -- 20 of 50 - 'And he lived happily ever after, to the end of his days.'";
      };
  };
