      [6] = {
        "Collect Fortune -- 36 of 50 - You should carry food with you in case you get hungry.";
      };
      [7] = {
        "Collect Fortune -- 37 of 50 - What about a bit of rope? You'll want it, if you haven't got it.";
      };
      [8] = {
        "Collect Fortune -- 38 of 50 - Shadows are darker than most places, so you will not be able to see as much when standing in them.";
