      };
      [4] = {
        "Collect Fortune -- 44 of 50 - ..And I must follow...";
      };
      [5] = {
        "Collect Fortune -- 45 of 50 - ...if I can.";
      };
      [6] = {
        "Collect Fortune -- 46 of 50 - Pursuing it with eager feet...";
      };
      [7] = {
        "Collect Fortune -- 47 of 50 - ...Until it joins some larger way...";
      };
      [8] = {
        "Collect Fortune -- 48 of 50 - ...Where many paths and errands meet...";
      };
      [9] = {
        "Collect Fortune -- 49 of 50 - ...And whither then...?";
      };
      [10] = {
        "Collect Fortune -- 50 of 50 - ...I cannot say.";
