      [5] = {
        "Obtain the Map of Zelem-melek - This map highlights the area of Moria known as Zelem-melek";
      };
      [6] = {
        "Obtain a Map of Nud-melek - This map highlights the important locations of the area know as Nud-melek in Moria.";
