      [7] = {
        "Obtain a map of the Foundations of Stone - This map details the location know as the Foundations of Stone within Moria.";
      };
      [8] = {
        "Obtain a map of the Redhorn Lodes - This map highlights the important locations of the area known as the Redhorn Lodes in Moria.";
      };
      [9] = {
        "Obtain a Map of Zirakzigil - This map shows a location on the side of the mountains outside of Moria.";
      };
      [10] = {
        "Obtain a map of the Flaming Deeps - This map highlights the important locations of the areas known as the Flaming Deeps in Moria.";
      };
      [11] = {
        "Obtain a map of the Grand Stair - This map details a location that was once a major crossing of passages in Moria; now, it is home to the many factions of goblin-kinds in the depths.";
