  };
  -- Race & Social / Cartographile -- Eriador
  [1879206037] = {
      [1] = {
        "Obtén el mapa del Bosque Viejo - El Bosque Viejo es un lugar que es mejor evitar, ya que los peligros se encuentran en cada esquina. Has obtenido una copia de un mapa del Bosque Viejo.";
      };
      [2] = {
        "Obtain the map of Archet - A small village in Bree, Archet recently was burned by the Blackwold brigands. You have acquired a map of the town and surrounding areas.";
      };
      [3] = {
        "Obtain the map of Bree-town - Bree-town is the main city of Bree-land. Such famous places as Inn of the Prancing Pony and the Boar Fountain are found within the city. You have found a wonderful map of Bree-town.";
      };
      [4] = {
        "Obtain the map of Annúminas - Once the home of the Kings of Men, Annúminas is now a flooded city on the southern bank of Lake Evendim in the region of Evendim. This is the map of the city.";
      };
      [5] = {
        "Obtain the map of the Ettenmoors - The Ettenmoors is a forgotten area of the world where evil has crept into nearly every part of the land. This is a map of the area.";
      };
      [6] = {
        "Obtain the map of the Northern Barrow-downs - The Men of Bree try to steer clear of the old burial mounds of the Men of Cardolan, for it is rumoured that terrifying creatures come out of the ground to stalk those among the mounds. This is a map of the northern part of the Barrow-downs.";
      };
      [7] = {
        "Obtain the map of Rivendell - Rivendell is the hidden valley where the Elves dwell on the border of the Misty Mountains and the Trollshaws. This is a map of that valley.";
      };
      [8] = {
        "Obtain the map of Eregion - Eregion was a home to the Elves in ages past; now, ruins cover a harsh landscape. This is a map of that land.";
      };
      [9] = {
        "Obtain the map of Enedwaith - A section of land leading south between Eregion and Dunland, Enedwaith is a harsh land of stone and wild. This is a map of the region.";
      };
      [10] = {
        "Obtain the map of Thorin's Gate - This small community of dwarves rests in the shadow of Thorin's Hall. This is a map of that area.";
      };
      [11] = {
        "Obtain the map of Forochel - A cold and forbidding land claimed by the Lossoth, Forochel lies far to the north. This is a map of those frozen lands.";
      };
      [12] = {
        "Obtain the map of Frostbluff - A town of rich and poor needing assistance in the wintry months. This is a map of the town.";
      };
      [13] = {
        "Obtain the map of the Southern Barrow-downs - The southern section of the Barrow-downs houses more ruins and mounds of ancient Men. This is a map of the area.";
      };
      [14] = {
        "Obtain the map of Bree-land - A fertile land where many Men make their homes. This is a map of the area.";
      };
      [15] = {
        "Obtain the map of the Shire - A place which most hobbits call home. The Shire is a collection of many smaller territories that make up the large land belonging to the hobbit-folk. This is a map of the area.";
      };
      [16] = {
        "Obtain the map of Ered Luin - Ered Luin is home to both Elves and dwarves, and each is none too fond of mixing with the other. This is a map of the area.";
      };
      [17] = {
        "Obtain the map of the Lone-lands - The Lone-lands is a lonely stretch heading east through the ruins of Men. This is a map of the area.";
      };
      [18] = {
        "Obtain the map of the North Downs - War has come to the Men of the North Downs, and they are in need of aid. This is a map of the area.";
      };
      [19] = {
        "Obtain the map of the Trollshaws - The land here is forbidding and grim with trolls wandering through the wild lands day and night. This is a map of the area.";
      };
      [20] = {
        "Obtain the map of the Misty Mountains - Cold wind and the bite of goblin-wrought blades await travellers in the Misty Mountains. This is a map of the area.";
      };
      [21] = {
        "Obtain the map of Angmar - The harsh land where the Witch-king once ruled. Now, the land is ruined and evil spreads freely and nearly unchecked. This is a map of the area.";
      };
  };
