  -- Epic / Lhaid Ogo Exploration
  [1879206112] = {
      [1] = {
      ["NAME"] = "Lhaid Ogo is a series of tunnels beneath the Lich Bluffs, in Enedwaith. Its passages are clogged with mud and not entirely stable."; 
      ["PROGRESS"] = "Delve into Lhaid Ogo and unravel its mysteries"; 
      ["LORE"] = "Lhaid Ogo is a series of tunnels beneath the Lich Bluffs, in Enedwaith. Its passages are clogged with mud and not entirely stable."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "95.60S"; 
          ["LONG"] = "54.77E"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Trapped behind a wooden wall in the depths of Lhaid Ogo, you found the body of an ancient unfortunate. Did he die there in the wall or was he moved to that spot to languish for all the ages?"; 
      ["PROGRESS"] = "Find the ancient, unlucky explorer"; 
      ["LORE"] = "Trapped behind a wooden wall in the depths of Lhaid Ogo, you found the body of an ancient unfortunate. Did he die there in the wall or was he moved to that spot to languish for all the ages?"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "95.44S"; 
          ["LONG"] = "55.10E"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "The wooden bridge was of ancient construction, but the damp rotted some of the railings away. The gap could then be used to drop down to the lower passage, but it would be a one-way journey."; 
      ["PROGRESS"] = "Find the gap in the bridge"; 
      ["LORE"] = "The wooden bridge was of ancient construction, but the damp rotted some of the railings away. The gap could then be used to drop down to the lower passage, but it would be a one-way journey."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "95.53S"; 
          ["LONG"] = "55.77E"; 
        }; 
      }; 
      };
      [4] = {
        "Find the discarded pouch";
      };
      [5] = {
      ["NAME"] = "Someone was eating a rat in the depths of Lhaid Ogo, but who? And what caused him not to finish it?"; 
      ["PROGRESS"] = "Find the unfinished dinner"; 
      ["LORE"] = "Someone was eating a rat in the depths of Lhaid Ogo, but who? And what caused him not to finish it?"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "95.82S"; 
          ["LONG"] = "55.02E"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Mud-eater has stalked the passages of Lhaid Ogo for many years and makes his lair in the deepest chamber. He drags prey back to his lair before feasting on it."; 
      ["PROGRESS"] = "Find Mud-eater's lair"; 
      ["LORE"] = "Mud-eater has stalked the passages of Lhaid Ogo for many years and makes his lair in the deepest chamber. He drags prey back to his lair before feasting on it."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "95.53S"; 
          ["LONG"] = "55.95E"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Deep within Lhaid Ogo, you found signs of something heavy being dragged up a muddy slope, and it filled your heart with worry."; 
      ["PROGRESS"] = "Find the disturbed earthen slope"; 
      ["LORE"] = "Deep within Lhaid Ogo, you found signs of something heavy being dragged up a muddy slope, and it filled your heart with worry."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "95.68S"; 
          ["LONG"] = "55.71E"; 
        }; 
      }; 
      };
  };
