  [1879220083] = {
      [1] = {
        "Complete the deed 'Half-orc Slayer'";
      };
      [2] = {
        "Derrota a los semiorcos en las Tierras Brunas - Los semiorcos de Saruman son leales... ¡siempre que sus enemigos sean más débiles que ellos!";
