  -- Great River / Limlight Gorge Explorer
  [1879230977] = {
      [1] = {
      ["NAME"] = "Limlight Gate-house"; 
      ["PROGRESS"] = "Discover the Limlight Gate-house"; 
      ["LORE"] = "When the last inhabitants of the Limlight Gorge were driven out by the arrival of trolls from the Misty Mountains, the Rohirrim erected this guard-post to keep an eye on the entrance to the Gorge and ensure that nothing came out of it unseen. Luckily, the trolls dare not stray too far from the caves and ledges they take cover beneath during cloudless days, and so they have made no attempt to come up out of the Gorge."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "25.43S"; 
          ["LONG"] = "66.99W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Limlight Falls"; 
      ["PROGRESS"] = "Discover Limlight Falls"; 
      ["LORE"] = "The Limlight Falls mark the bottom extent of the foothills leading down from the Misty Moutains as the rushing river empties out towards the plains to the south.\n\nThe cold rushing stream ensures a steady supply of fresh water for the community of Stangard."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "28.50S"; 
          ["LONG"] = "72.32W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Limlight Glade"; 
      ["PROGRESS"] = "Discover the Ent-grove"; 
      ["LORE"] = "The northernmost extent of the forest of Fangorn ends here, at the banks of the Limlight River.\n\nThe Ents have long had a small gathering place here, where they would long ago meet with the Elves of Lothlórien and learn news of the outside world."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "29.41S"; 
          ["LONG"] = "72.08W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "The Fallen Tower"; 
      ["PROGRESS"] = "Discover the Fallen Watch-tower"; 
      ["LORE"] = "This ancient Gondorian tower once watched over the Limlight Gorge.\n\nTo what purpose, or against what threat, no-one today remembers, for it fell into ruin long, long ago."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "28.14S"; 
          ["LONG"] = "68.63W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "The Pothole"; 
      ["PROGRESS"] = "Discover the Pothole"; 
      ["LORE"] = "This old river pothole remains from time long past when the Limlight's course ran further up the Gorge. It left this oddly smoothed pit behind as it shifted course.\n \nNow, alas, it seems that trolls have taken up residence within its deep shadows."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "27.28S"; 
          ["LONG"] = "71.25W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Prospector's Shack"; 
      ["PROGRESS"] = "Discover the Prospector's Shack"; 
      ["LORE"] = "This may once have been a homestead or hunting-cabin down in the Gorge, but more recently it has been the way-post for a band of prospectors and treasure-seekers exploring the Gorge for valuable minerals."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "27.03S"; 
          ["LONG"] = "69.87W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Old Sawmill"; 
      ["PROGRESS"] = "Discover the Old Sawmill"; 
      ["LORE"] = "This old sawmill was built some years ago by the Men of Stangard, before the trolls arrived and drove them away.\n\nMore recently it appears that a band of hard-working but obstinately foolish dwarves have been trying to restore the mill to working order."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "28.96S"; 
          ["LONG"] = "69.71W"; 
        }; 
      }; 
      };
  };
