  -- Central Gondor / Path of the Grey Host
  [1879316264] = {
      [1] = {
      ["NAME"] = "Ethring"; 
      ["PROGRESS"] = "Discover Ethring"; 
      ["LORE"] = "You have discovered the village of Ethring, which stands on either side of the main fords of the Ringló. It is a rustic village of lumberers and fisher-folk with a mighty hall upon a nearby knoll. Timbers hewn in its woods are sent downstream to Amroth and south, overland, to the Ethir and Pelargir."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "71.84S"; 
          ["LONG"] = "50.10W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Camp of the Grey Host"; 
      ["PROGRESS"] = "Discover the Camp of the Grey Host"; 
      ["LORE"] = "You have discovered the Camp of the Grey Host, a stop for Aragorn and his men before they march on Pelargir."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "82.49S"; 
          ["LONG"] = "37.57W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Linhir"; 
      ["PROGRESS"] = "Discover Linhir"; 
      ["LORE"] = "You have discovered the city of Linhir which straddles the river on either side, guarding a ford and bridge. Part of the town belongs to Lebennin, and part to Belfalas. It is normally a quiet harbor of fisherfolk, but has been assailed and partially destroyed by the Haradrim and Corsairs of Umbar, who besieged it and fought long against its defenders, led by Lord Angbor of Lamedon and Comeldir, a swan-knight entrusted by Prince Imrahil with guardianship over the far reaches of his province."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "81.48S"; 
          ["LONG"] = "45.44W"; 
        }; 
      }; 
