  -- Central Gondor / Vanguard of Central Gondor
  [1879316269] = {
      [1] = {
        "Complete the epilogue of Ringló Vale - The Ruthless Dead found themselves hopelessly bound to their oath, and banished far from their Master.\n\nDrugât grew weary, and asked your aid in reclaiming gifts once given Isildur and his men. In exchange, his cursed folk would return to the Paths of the Dead and never again trouble the lands of the Living.\n\nYou held your word and for once, Drugât upheld his. He and the Ruthless Host have left Gondor in peace, hoping that one day, they shall finally be at rest.";
      };
      [2] = {
        "Complete the quest 'Epilogue: The Waters of the Gilrain'";
      };
      [3] = {
        "Complete the quest 'Epilogue: Sailing Into The Dawn'";
      };
  };
