      };
  };
  -- Class / A Thousand Stingers
  [1879317531] = {
      [1] = {
        "Usa Enjambre de abejas - Has profundizado tu comprensión del temperamento de estas pequeñas criaturas y las manejas con mayor eficacia en la batalla.";
      };
  };
  -- Class / Class Deeds - Tier 5
  [1879317532] = {
