  -- Class / Natural Beorn Leadership
  [1879317533] = {
      [1] = {
        "Usa Reconfortar - Eres una fuente de confianza para tus compañeros.";
      };
  };
  -- Class / Rattling Roar
  [1879317534] = {
      [1] = {
        "Suelta un Rugido feroz - Se corre la voz por toda la Tierra Media de tus hazañas, tus habilidades, pero sobre todo, de tu rugido.";
      };
  };
  -- Class / Get Your Bearings
  [1879317535] = {
      [1] = {
        "Entra en forma de oso - Has aprendido a transformarte rápidamente incluso durante la batalla más intensa.";
      };
  };
  -- Class / Class Deeds - Tier 2
