  -- The Grey Mountains / Delver of Thikil-gundu
  [1879370341] = {
      [1] = {
      ["NAME"] = "Durûz-mazal, the Chamber of Faces"; 
      ["PROGRESS"] = "Discover Durûz-mazal, the Chamber of Faces"; 
      ["LORE"] = "You have discovered Durûz-mazal, the Chamber of Faces. Erected to honour the Dwarrowmoot of old between the Seven Kings of the Dwarves, the many faces of this chamber watch over Thikil-gundu."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.29N"; 
          ["LONG"] = "136.01W"; 
        }; 
