      };
      [2] = {
      ["NAME"] = "Bekâr-mazal, the Arming-chamber"; 
      ["PROGRESS"] = "Discover Bekâr-mazal, the Arming-chamber"; 
      ["LORE"] = "You have discovered Bekâr-mazal, the Arming-chamber. Despite housing many weapons and tools of war, the great armoury of Thikil-gundu did not avail the Dwarves of the Steel Keep in the battle against Vethúg Wintermind."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.12N"; 
          ["LONG"] = "136.69W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "The Smithies of Kall-khebâb"; 
      ["PROGRESS"] = "Discover the Smithies of Kall-khebâb"; 
      ["LORE"] = "You have discovered the Smithies of Kall-khebâb. Once a great craft-hall of Thikil-gundu, the old smithies of the Steel Keep have been seized by the Orcs of Gundabad in service to the brood of Vethúg Wintermind and his forebear, Hrímil Frost-heart."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.28N"; 
          ["LONG"] = "135.44W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Balb-gundu, the Frostdelf"; 
      ["PROGRESS"] = "Discover Balb-gundu, the Frostdelf"; 
      ["LORE"] = "You have discovered Balb-gundu, the Frostdelf. One of the only remaining delvings of Thikil-gundu, the Frostdelf once comprised much of Thikil-gundu until a great portion of it collapsed into the Depths of Akhatâr. It now serves as the lair of Athramóth, the mate of Vethúg Wintermind and mother of countless dragon-kind in the Grey Mountains."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.27N"; 
          ["LONG"] = "134.96W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Zashar-tûmun, the Ruin-dwellings"; 
      ["PROGRESS"] = "Discover Zashar-tûmun, the Ruin-dwellings"; 
      ["LORE"] = "You have discovered Zashar-tûmun, the Ruin-dwellings. Once a great dwelling-hall of the Dwarves of Thikil-gundu, Zashar-tûmun has fallen to ruin."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "24.13N"; 
          ["LONG"] = "136.80W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "The Feast-house of Amrâg-zahar"; 
      ["PROGRESS"] = "Discover the Feast-house of Amrâg-zahar"; 
      ["LORE"] = "You have discovered the Feast-house of Amrâg-zahar. In the course of many long years, both the Longbeards and Zhélruka enjoyed great feasts and merriment in Amrâg-zahar before the fall of the Steel Keep. When Durin's Folk sought to return to Thikil-gundu, it was there Vethúg Wintermind waited in ambush and descended to slay Dáin, Frór, and countless other Longbeards."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.92N"; 
          ["LONG"] = "136.00W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "The Lore-trove of Afhân-binnîn"; 
      ["PROGRESS"] = "Discover the Lore-trove of Afhân-binnîn"; 
      ["LORE"] = "You have discovered the Lore-trove of Afhân-binnîn. A great hall of lore lost to the Longbeards and Zhélruka. Many of its works have been brought to ruin, either by time or by the breath of cold-drakes, but a few pieces of note may still remain in the shadows of Afhân-binnîn."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "24.03N"; 
          ["LONG"] = "135.41W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "The Depths of Akhatâr"; 
      ["PROGRESS"] = "Discover the Depths of Akhatâr"; 
      ["LORE"] = "You have discovered the Depths of Akhatâr. These shadowed pits have not been mapped by any living dwarf, but who knows what could dwell in the depths of the Grey Mountains?"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.93N"; 
          ["LONG"] = "134.96W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Razûkh-zahari, the Room of Rain"; 
      ["PROGRESS"] = "Discover Razûkh-zahari, the Room of Rain"; 
      ["LORE"] = "You have discovered Razûkh-zahari, the Room of Rain. A great underground river travels beneath the Grey Mountains, and passes through a carefully-delved crack above the Room of Rain."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "24.59N"; 
          ["LONG"] = "135.34W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Thikil-nesad, the Steel Seat"; 
      ["PROGRESS"] = "Discover Thikil-nesad, the Steel Seat"; 
      ["LORE"] = "You have discovered Thikil-nesad, the Steel Seat. Once the seat of countless Kings of the Longbeards and Zhélruka, Thikil-nesad was abandoned when the Steel Keep fell to Vethúg Wintermind."; 
      ["POINTS"] = {
