  -- Vales of Anduin / A Chronicle of the Company
  [1879387421] = {
      [1] = {
      ["NAME"] = "He was through, with coat torn, running down the steps, while confused goblins were still picking up his buttons at the gate."; 
      ["PROGRESS"] = "Where Bilbo lost his buttons"; 
      ["LORE"] = "He was through, with coat torn, running down the steps, while confused goblins were still picking up his buttons at the gate."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "12.10N"; 
          ["LONG"] = "63.37W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "How they jumped! Gandalf was astonished, as they all shouted with surprise and delight."; 
      ["PROGRESS"] = "Where Bilbo reunites with the Company"; 
      ["LORE"] = "How they jumped! Gandalf was astonished, as they all shouted with surprise and delight."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "10.91N"; 
          ["LONG"] = "61.23W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "You would have laughed, if you had seen the dwarves, up in the trees with their beards hanging down, like old gentlemen."; 
      ["PROGRESS"] = "Where the Company encountered Wargs"; 
      ["LORE"] = "You would have laughed, if you had seen the dwarves, up in the trees with their beards hanging down, like old gentlemen."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "11.04N"; 
          ["LONG"] = "59.75W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Gandalf, had once kindly assisted the eagles and healed their lord from an arrow-wound."; 
      ["PROGRESS"] = "Where the Eagles took the Company to safety"; 
      ["LORE"] = "Gandalf, had once kindly assisted the eagles and healed their lord from an arrow-wound."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "14.71N"; 
          ["LONG"] = "61.04W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "'Farewell! Wherever you fare, until your eyrie receive you at your journey's end!'"; 
      ["PROGRESS"] = "Where the Eagles set down the Company"; 
      ["LORE"] = "'Farewell! Wherever you fare, until your eyrie receive you at your journey's end!'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "13.05N"; 
          ["LONG"] = "58.46W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "'This is not my adventure. I may look in on you again before it is over, for I have some rather pressing business to attend to.'"; 
      ["PROGRESS"] = "Where the Company gathered at the Carrock"; 
      ["LORE"] = "'This is not my adventure. I may look in on you again before it is over, for I have some rather pressing business to attend to.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "13.48N"; 
          ["LONG"] = "57.85W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "They were bigger than your thumb, much bigger, and the bands of yellow on their black bodies shone a radiant gold."; 
      ["PROGRESS"] = "Where the Company walked through Beorn's bee-pastures"; 
      ["LORE"] = "They were bigger than your thumb, much bigger, and the bands of yellow on their black bodies shone a radiant gold."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "13.10N"; 
          ["LONG"] = "54.47W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "'Here they are! They don't look dangerous.' Beorn laughed a great, low laugh, and put down his axe."; 
      ["PROGRESS"] = "Where the Company came upon Beorn's house"; 
      ["LORE"] = "'Here they are! They don't look dangerous.' Beorn laughed a great, low laugh, and put down his axe."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "13.86N"; 
          ["LONG"] = "53.32W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "'A very good tale!' said Beorn. 'The best I have heard for a long while. Let's have something to eat!'"; 
      ["PROGRESS"] = "Where Beorn meets the Company"; 
      ["LORE"] = "'A very good tale!' said Beorn. 'The best I have heard for a long while. Let's have something to eat!'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "13.40N"; 
          ["LONG"] = "53.31W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "The dwarves' beards quivered as they listened, for they knew that soon they must venture into the Mirkwood."; 
      ["PROGRESS"] = "Where the Company had supper with Beorn"; 
      ["LORE"] = "The dwarves' beards quivered as they listened, for they knew that soon they must venture into the Mirkwood."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "38.80N"; 
          ["LONG"] = "53.16E"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "'I hope you like the look of it. Now you must send back Beorn's ponies that you have borrowed.'"; 
      ["PROGRESS"] = "Where the Company enters the Mirkwood"; 
      ["LORE"] = "'I hope you like the look of it. Now you must send back Beorn's ponies that you have borrowed.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "15.71N"; 
          ["LONG"] = "51.18W"; 
        }; 
      }; 
      };
      [12] = {
      ["NAME"] = "There, far away was the Lonely Mountain on the edge of the horizon. Snow remaining on its highest peak, unmelted and gleaming."; 
      ["PROGRESS"] = "Where Bilbo returns home"; 
      ["LORE"] = "There, far away was the Lonely Mountain on the edge of the horizon. Snow remaining on its highest peak, unmelted and gleaming."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "9.78N"; 
          ["LONG"] = "64.98W"; 
        }; 
      }; 
      };
  };
