  -- Vales of Anduin / Vales Beast and Insect Slayer
  [1879387439] = {
      [1] = {
        "Defeat many beasts and insects in the Vales of Anduin - 'The Vales of Anduin are home to many varieties of beast and insect that will do you no harm. But there are others that have been seized by the darkness that crept out of Mirkwood, or have been tamed by the Orcs and goblins of the Misty Mountains. Oh yes, there are some that will do you a great deal of harm, if you let them! Show those foes no mercy, to save the rest!' - Radagast the Brown";
      };
  };
  -- Vales of Anduin / Vales Orc-slayer
  [1879387440] = {
      [1] = {
        "Defeat many Orcs and half-orcs in the Vales of Anduin - 'Half-orcs are twice the trouble.' - Unknown";
      };
  };
  -- Vales of Anduin / Vales Dead-slayer (Advanced)
  [1879387441] = {
      [1] = {
        "Complete the deed 'Vales Dead-slayer'";
      };
      [2] = {
        "Defeat many dead in the Vales of Anduin - 'Whatever has caused these spirits to appear in the Vales of Anduin, you will know what I know when I know it, and not before! I try not to speculate without knowing all of the facts.' - Gandalf the White, Known Speculator";
      };
  };
  -- Vales of Anduin / Vales Goblin-slayer
  [1879387442] = {
      [1] = {
        "Defeat many goblins in the Vales of Anduin - 'I hate goblins in all their forms. I have never worried about the particulars. Orcs, goblins, hobgoblins... they are all the same to me.' - Grimbeorn the Old";
      };
  };
  -- Vales of Anduin / Vales Orc-slayer (Advanced)
  [1879387443] = {
      [1] = {
        "Complete the deed 'Vales Orc-slayer'";
      };
      [2] = {
        "Defeat many Orcs and half-orcs in the Vales of Anduin - 'Anyone who says that half-orcs are twice the trouble has never had the pleasure of facing down a raiding party of pillaging Orcs. I would take two half-orcs for every one of their full-blooded cousins.' - Skalla, Captain of Vegbár";
      };
  };
  -- Vales of Anduin / Slayer of the Vales
  [1879387444] = {
      [1] = {
        "Complete: Vales Beast and Insect Slayer (Advanced) - You have become known as an exceptional hunter among the Wilderfolk of the Vales of Anduin.";
      };
