  -- Minas Morgul / Discovery: Gorthad Nûr, the Deep-barrow
  [1879390878] = {
      [1] = {
      ["NAME"] = "Gorthad Nûr, the Deep-barrow"; 
      ["PROGRESS"] = "Discover the entrance to Gorthad Nûr, the Deep-barrow"; 
      ["LORE"] = "These were the burial-houses of Minas Ithil, where the bones of the dead were laid to rest in solemn state, but that was long ago. Now this place has fallen to darkness and evil, and it is called Gorthad Nûr, the Deep-barrow. Vengeful shades and foul kergrim have been drawn to the tombs, and they will not allow any incursion into the domain they have taken for their own."; 
      ["POINTS"] = {
