  [1879390894] = {
      [1] = {
      ["NAME"] = "Eithel Gwaur"; 
      ["PROGRESS"] = "Discover the entrance to Eithel Gwaur, the Filth-well"; 
      ["LORE"] = "The river ran clean, once, but now it is called the Morgulduin, and its waters are foul and dirty. The source of this corruption may be found within Eithel Gwaur, the Filth-well, used by the Nazgûl as a dumping ground of the slain. It is choked with rotting flesh, old bones, and noxious slime."; 
