  -- Imlad Morgul / Orc-kind Slayer of Imlad Morgul (Advanced)
  [1879395345] = {
      [1] = {
        "Complete the deed 'Orc-kind Slayer of Imlad Morgul'";
      };
      [2] = {
        "Defeat many Orc-kind in Imlad Morgul - 'They call it the Harrowing,' one young soldier in Echad Uial whispered to his captain. 'The Orcs battle for control of the lowest level of the city, and neither faction can wrest the upper hand away from the other.'\n\n'The Harrowing, eh?' his captain answered. 'What do you call it?'\n\nThe young soldier looked first one way and then the other, and lowered his voice.\n\n'Orc fight,' he whispered. His captain nodded, and handed the soldier a whetstone.\n\n'Good enough for me,' he said.";
      };
  };
  -- Imlad Morgul / Wight-slayer of Imlad Morgul
  [1879395346] = {
