      [5] = {
      ["NAME"] = "Estolad Lân"; 
      ["PROGRESS"] = "Explore Estolad Lân"; 
      ["LORE"] = "Anborn, Ranger of Ithilien, has established the camp of Estolad Lân on the western side of Rath Dúath. From there he seeks to carry out the commands of Prince Faramir of Ithilien, though the camp rests nearly beneath the very shadow of Minas Morgul."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "64.61S"; 
          ["LONG"] = "2.02W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Echad Uial"; 
      ["PROGRESS"] = "Explore Echad Uial"; 
      ["LORE"] = "Prince Faramir's White Company established the camp of Echad Uial on the eastern side of Rath Dúath, intending to marshal expeditions into Minas Morgul itself. But they have spent much attention maintaining the watch on the Dread Door of Fennas Gost, and there are never enough adventurers willing to face the Dead City."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "65.01S"; 
          ["LONG"] = "4.11E"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Râkh Mathán"; 
      ["PROGRESS"] = "Explore Râkh Mathán"; 
      ["LORE"] = "The warg dens of Râkh Mathán extend up into the hills surrounding Rath Dúath, and the creatures' wailing howls strike fear even into the brave hearts of Faramir's Rangers. Especially the Rangers, for they have experienced much grief at the teeth and claws of the beasts during the last several months, as the wargs have ranged further from their dens at the command of their Orkish masters."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "63.39S"; 
          ["LONG"] = "4.14E"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Banám Lugaun"; 
      ["PROGRESS"] = "Explore Banám Lugaun"; 
      ["LORE"] = "The Orc encampment of Banám Lugaun sees a great deal of activity during both night and day, serving as a waypoint of sorts for servants of evil on their way to one place or another within Imlad Morgul."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "63.30S"; 
          ["LONG"] = "1.07E"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Shakam Moz"; 
      ["PROGRESS"] = "Explore Shakam Moz"; 
      ["LORE"] = "The merrevail roost of Shakam Moz watches over both Rath Dúath and Lhingris from the high peak, and the minions of Lhaereth the Stained prove a terror for all who are forced to travel in those valleys."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "66.88S"; 
          ["LONG"] = "8.37E"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Dáru Lagúrz, the Broken Houses"; 
      ["PROGRESS"] = "Explore Dáru Lagúrz, the Broken Houses"; 
      ["LORE"] = "Vile and unpleasant kergrim have settled into Dáru Lagúrz, picking over the remains. Filth and disease have followed them into the Broken Houses, vile dangers to be faced by those few who must gain entrance to that one-time place of rest."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "67.74S"; 
          ["LONG"] = "4.90E"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "Taen Orwath"; 
      ["PROGRESS"] = "Explore Taen Orwath"; 
      ["LORE"] = "Few of the Rangers of Ithilien have braved the hills of Rath Dúath. There upon an overlook, those few have established the small encampment of Taen Orwath."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "66.85S"; 
