  -- Imlad Morgul / Imlad Morgul -- The Reclamation
  [1879395369] = {
      [1] = {
        "Complete quests in the reclamation of Minas Ithil - For every difficult task you accomplished, servants of the Enemy sought to oppose it. But they were unable to succeed in these attempts, for always did you dare one more foray into Imlad Morgul, one more incursion to the Dead City.";
      };
  };
  -- Imlad Morgul / Scouting Cirith Ungol
  [1879395370] = {
      [1] = {
      ["NAME"] = "The Straight Stair"; 
      ["PROGRESS"] = "Explore the Straight Stair"; 
      ["LORE"] = "This is the first of the stairs climbed by Frodo Baggins, Samwise Gamgee, and the creature Gollum by which they intended to gain access to the Land of Mordor. The stairs are tall and steep, and while the climb is straight and without turns, the steps are uneven and treacherous. The stairs are cut into the flanks of the Ephel Dúath and climb from the floor of the valley up to the pass itself, on the western side of Cirith Ungol."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "62.72S"; 
          ["LONG"] = "0.54W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "The Winding Stair"; 
      ["PROGRESS"] = "Explore the Winding Stair"; 
      ["LORE"] = "This second stair begins high above the valley floor, and unlike the Straight Stair it weaves back and forth along the cliffside, a great chasm yawning to one side. At the top of the stairs, a dark cleft leads onward to the entrance of Torech Ungol and the horrors within."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "62.05S"; 
          ["LONG"] = "2.17E"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Echad Taerdim"; 
      ["PROGRESS"] = "Explore Echad Taerdim"; 
      ["LORE"] = "Mablung has established the small camp of Echad Taerdim at the top of the Straight Stair, and he intends to use it as a base from which to mount small expeditions into nearby Cirith Ungol."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "61.92S"; 
          ["LONG"] = "0.53W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Cadar Skûs"; 
      ["PROGRESS"] = "Explore Cadar Skûs"; 
      ["LORE"] = "The Ungoledain have come a long way overland across Middle-earth, following a call only they can hear, and they have established the resting-place of Cadar Skûs in the mountains. Is their long journey finally near its end?"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "59.26S"; 
          ["LONG"] = "1.08W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Torech Ungol"; 
      ["PROGRESS"] = "Explore Torech Ungol"; 
      ["LORE"] = "The pass of Cirith Ungol was rarely left unguarded, but few only would dare to make the crossing while the Orcs of the tower could spy on them from above. The worse and far greater danger was spoken of only in whispers, for few good folk knew even rumour of it. Some dark terror dwelled in the tunnel of Torech Ungol, through which the path must lead. Even should a traveller make it safely through the web-haunted passage, the tunnel gave way to a chasm open to the sky but riddled with cave-mouths on each cliffside from which any foe might have the advantage of surprise. No tactician would advise taking that road.\n\nIt was the favourite hunting-ground of Ungwetári, last daughter of Ungoliant, and only the very foolish or the very desperate should go that way."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "27.33N"; 
          ["LONG"] = "12.74E"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Remmorchant, the Net of Darkness"; 
      ["PROGRESS"] = "Explore the Remmorchant"; 
      ["LORE"] = "None have seen beyond the entrance to Remmorchant, the Net of Darkness, for that is the deepest and most subterranean of Ungwetári's tunnels, the pitted and sunless abyss into which she retreated after her unexpected injury at the hands of Samwise Gamgee and the point of Sting, the Gondolin-forged blade wielded by both Bilbo and Frodo Baggins, and later by the terrified but deadly gardener of Bag End.\n\nUngwetári knew nothing of those hobbits or the lineage of that blade, but she remembers the pain of that encounter, and it has built in her a white-hot and blinding rage. In Remmorchant she broods upon her wound, and festers in her hatred."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "34.63N"; 
          ["LONG"] = "14.08E"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Taurlingol"; 
      ["PROGRESS"] = "Explore Taurlingol"; 
      ["LORE"] = "The forest of Taurlingol has become spider-infested, a place of webs and unnatural voices. If the Ungoledain can understand the chittering of their idols, they are unwilling to share its meaning. This is probably a good thing."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "60.11S"; 
          ["LONG"] = "3.24E"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Kaslokroz"; 
      ["PROGRESS"] = "Explore Kaslokroz"; 
      ["LORE"] = "Uruks following the commands of Rukhor the Pale Herald have established this camp atop the Winding Stair, west of Cirith Ungol. It seems they have run afoul of the Ungoledain and spiders ranging out of Taurlingol and Torech Ungol, which is unsurprising. Expectedly, some uruks have also fallen to infighting among themselves and with other Orc-bands creeping down from the tower and through the pass."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "61.66S"; 
          ["LONG"] = "1.83E"; 
        }; 
      }; 
      };
  };
