  -- Wells of Langflood / Wells of Langflood Goblin and Orc-slayer
  [1879405903] = {
      [1] = {
        "Defeat goblins and Orcs in the Wells of Langflood - The question of these times, of great interest for Runerik Knotbeard and his people, not to mention the other folk who walk along the Wells of Langflood: are the Orcs and goblins who threaten these lands driven by the same hatreds and desires that have motivated them for hundreds of years, or is there a greater purpose that guides them to evil? It is a question that must be resolved, for it could mean the survival of those who live along the Langflood.";
      };
  };
  -- Wells of Langflood / Natural Formations in the Wells of Langflood
  [1879405904] = {
      [1] = {
      ["NAME"] = "Tithroz"; 
      ["PROGRESS"] = "Explore Tithroz"; 
      ["LORE"] = "The Floodfells are riddled with caves, but the Beornings who live in this area prefer not to explore their dark, narrow depths. Vile insects, pestilential bats, and burrowers with sharp teeth make their homes in these places, and the folk of Limlók only wish to concern themselves with these unpleasant creatures if they emerge into the sunlight or moonlight."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "25.86N"; 
          ["LONG"] = "1.47W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Reikfoss of Greylin"; 
      ["PROGRESS"] = "Explore Reikfoss of Greylin"; 
      ["LORE"] = "The great cascade of Reikfoss marks the location where the River Greylin flows out of the Elderslade into Misthallow to form one of the falls of the Three Sisters. Together, the vapours that rise from the base of Reikfoss and those of the Twainmantle blanket all of Misthallow in fog."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "31.85N"; 
          ["LONG"] = "60.03W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Twainmantle"; 
      ["PROGRESS"] = "Explore the Twainmantle"; 
      ["LORE"] = "The two waterfalls of the Twainmantle are formed at the passage of the Langwell and a smaller stream out of Elderslade into Misthallow. Together with the Reikfoss, these three falls make up the Three Sisters, the combined vapour that rises from their bases enshrouding all of Misthallow in fog."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "31.44N"; 
          ["LONG"] = "62.75W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Veithhól"; 
      ["PROGRESS"] = "Explore Veithhól"; 
      ["LORE"] = "The rocky slopes of Veithhól serve as a den for the hunting-cats that stalk Misthallow. What few travellers find themselves in this area report the sound of soft, padding feet somewhere in the fog. The natural consequence of these reports seems obvious to the wiser among us: the cats must not have been hungry, or these reports would not exist."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "30.52N"; 
          ["LONG"] = "58.31W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Scraper's Clough"; 
      ["PROGRESS"] = "Explore Scraper's Clough"; 
      ["LORE"] = "The narrow clefts of Scraper's Clough have been expanded by the tireless work of the cave-claws that live here, an industrious effort that is halted only when it is time for the creatures to feed. This they do on the hapless beasts that stumble into the Clough, and on adventurers who do the same. These latter meals tend to underestimate the creatures as 'mere cave-claws,' a misjudgment the inhabitants of Scraper's Clough are only too pleased to encourage."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "26.35N"; 
          ["LONG"] = "5.54W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Cabed Rhimdath"; 
      ["PROGRESS"] = "Explore the Cabed Rhimdath"; 
      ["LORE"] = "The rocky pass of the Cabed Rhimdath serves as a path for those of the Holbytlan who dare to venture from the safety of their home in Lyndelby. For those few who have travelled into the Cabed Rhimdath, they have reported thick brambles and strange painted stones before turning around at the site of leering Eagles."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "26.32N"; 
          ["LONG"] = "62.45W"; 
        }; 
      }; 
      };
  };
  -- Wells of Langflood / Quests of Misthallow
  [1879405905] = {
      [1] = {
        "Complete quests in Misthallow - You have completed many quests in the fog-enshrouded lands watched by the Protectors of Wilderland.";
      };
  };
  -- Wells of Langflood / Ruins in the Wells of Langflood
  [1879405906] = {
      [1] = {
      ["NAME"] = "Sundergrót"; 
      ["PROGRESS"] = "Find Sundergrót"; 
      ["LORE"] = "The history of Sundergrót is shrouded in mystery, for it has been long-abandoned. Longbeard tradition holds that this great cleft overlooking the Floodfells was made by the impact of Durin's axe sometime during the First Age.\n\nToday the ruins are haunted by goblins, but they know nothing of the ancient events that there took place. For the goblins it holds only the memory of dwarf-work, and that is a sharp dagger-point of hatred to them, though they covet the treasures and gems their foes unearth."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "31.84N"; 
          ["LONG"] = "33.19E"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "White Mare"; 
      ["PROGRESS"] = "Find the White Mare"; 
      ["LORE"] = "At some time during the residency of the Éothéod in these lands, they carved the White Mare into a hillside in the Floodfells. Whether its distinctive shape was intended to represent the mearas they found grazing on the strip of land between the Twainmantles and the Reikfoss is not known, but seems likely. The White Mare is today faded and somewhat overgrown, but it remains a reminder of the Éothéod's love of horses."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "22.26N"; 
          ["LONG"] = "56.29W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Skerabrygg"; 
      ["PROGRESS"] = "Find Skerabrygg"; 
      ["LORE"] = "The dwarf-bridge of Skerabrygg once permitted passage across the Langflood for those seeking to explore Sundergrót, but today the bridge is destroyed. Someone has hastily-repaired the span with planks of wood, but it seems a temporary solution. The weather and rain of the Floodfells will doubtless cast this path into the river before many days pass."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "17.92N"; 
          ["LONG"] = "58.70W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Hengi's Leap"; 
      ["PROGRESS"] = "Find Hengi's Leap"; 
      ["LORE"] = "Whoever Hengi may have been, and the knowledge of why this broken dwarf-bridge bears his name, has been lost to time."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.27N"; 
          ["LONG"] = "60.12W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Framsburg"; 
      ["PROGRESS"] = "Find Framsburg"; 
      ["LORE"] = "The great keep of the Ai-thúda was called Fasthálla, and it was the seat of their chief Frumgar. When it was burned and destroyed by Scatha the Worm, and Frumgar gravely wounded, his young son Fram swore vengeance upon the great wingless dragon. Eventually it was done, and Fram became Fram Wormsbane. The Ai-thúda rebuilt Fasthálla and gave it a new name: Framsburg.\n\nFrom its location high atop a rocky spur in Misthallow, Framsburg could not be easily-conquered by Orcs, though they tested its defences and the resolve of its inhabitants from time to time. After the departure of the Éothéod, Framsburg gradually fell into ruin through neglect. It was never sacked, but in time it stood empty and Orcs prowled the ruin.\n\nToday, worms and drakes have built nests among the skeletons of ancient buildings, and Framsburg is theirs. In this way perhaps Scatha has at last achieved his revenge upon Fram Wormsbane and the memory of his people."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "30.33N"; 
          ["LONG"] = "52.91W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Lumrog"; 
      ["PROGRESS"] = "Find Lumrog"; 
      ["LORE"] = "The hill-trolls and their unpleasant allies have erected a barricade at Lumrog, watching passage along the road and allowing none to pass. Whether this obstruction is motivated by selfish gain or has been mandated by more cunning powers with greater designs is unknown."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "28.41N"; 
          ["LONG"] = "59.54W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Stramvárth"; 
      ["PROGRESS"] = "Find Stramvárth"; 
      ["LORE"] = "The goblins of Stramvárth root among the ruins of Sundergrót in search of treasure, fighting among themselves for the right to hold the most precious pieces."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "19.25N"; 
          ["LONG"] = "59.22W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Egvárth"; 
      ["PROGRESS"] = "Find Egvárth"; 
      ["LORE"] = "The goblins and Orc-kind of Egvárth quarreled with their kindred to the east for the right to camp nearer to Sundergrót. It is a decision they may come to regret if more than treasures can be found in the depths of that cleft."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "20.71N"; 
          ["LONG"] = "60.68W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Dúnabrygg"; 
      ["PROGRESS"] = "Find Dúnabrygg"; 
      ["LORE"] = "Dúnabrygg crosses the river, allowing passage between Misthallow and the Floodfells. The stonework of the bridge has crumbled, but enterprising dwarves repaired the span with sturdy wooden construction."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "25.11N"; 
          ["LONG"] = "58.53W"; 
        }; 
      }; 
      };
  };
