  -- Wells of Langflood / Wells of Langflood Wood-troll Slayer
  [1879405909] = {
      [1] = {
        "Defeat many Wood-trolls in the Wells of Langflood - 'Taurogrim? Wood-trolls? Whatever you call them, they fear the axe and they fear the fire, and that is enough for me. But I would not recommend using them for kindling. They burn with a vile, choking smoke, and it fills the lungs with poison.' - Runerik Knotbeard";
      };
  };
  -- Wells of Langflood / Wells of Langflood Beast-slayer
  [1879405910] = {
      [1] = {
        "Defeat many beasts throughout the Wells of Langflood - You have proven yourself an excellent hunter of the beasts that stalk the Wells of Langflood.";
      };
  };
  -- Wells of Langflood / Explorer of the Wells of Langflood
  [1879405911] = {
