  -- Elderslade / Dragon-kind Slayer of Elderslade
  [1879411114] = {
      [1] = {
        "Defeat dragon-kind in Elderslade - After the fall of the realm of Grárik, dragon-kind spread across Ered Mithrin to the western reaches of Mount Gundabad. Although their numbers are fewer in the Third Age, their presence in Elderslade poses a constant threat to any who would dare to brave the North.";
      };
  };
