  -- Elderslade / Dwarf-ruins of Elderslade
  [1879411148] = {
      [1] = {
      ["NAME"] = "Hárveg Bridge"; 
      ["PROGRESS"] = "Discover the Hárveg Bridge"; 
      ["LORE"] = "Perched above the Greylin River, the Hárveg Bridge had been, until recently, broken and impassable. The dwarves have skilfully mended the bridge, opening safe passage to and from Misthallow once more."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "32.63N"; 
          ["LONG"] = "59.71W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Annâk-khurfu"; 
      ["PROGRESS"] = "Discover Annâk-khurfu"; 
      ["LORE"] = "Despite the many long years it has endured, Annâk-khurfu continues to stand tall. The dwarves have rallied to these ruins and called their allies to arms, preparing for the inevitable.\n\nAnnâk-khurfu offers an advantageous view of the main roads leading into Elderslade -- from Ered Mithrin to the east, and Misthallow to the south -- where friend and foe can be spotted plainly."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "32.74N"; 
          ["LONG"] = "61.12W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Zarkul-sulûn"; 
      ["PROGRESS"] = "Discover Zarkul-sulûn"; 
      ["LORE"] = "The years have not been kind to Zarkul-sulûn, which now plays host to all manner of evil: Orcs, hobgoblins, wargs, and perhaps others.\n\nThe ruins sit too closely to Annâk-khurfu for the dwarves' comfort. They keep a wary eye on Zarkul-sulûn, understanding that it will be the first of many obstacles they must cross if they wish to retake Gundabad."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "32.78N"; 
          ["LONG"] = "62.77W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Shakal-atrâd"; 
      ["PROGRESS"] = "Discover Shakal-atrâd"; 
      ["LORE"] = "The forces of Gundabad have long held Shakal-atrâd within their grasp. Though all appears quiet outside these foreboding ruins, delving deeper may reveal otherwise...."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "34.11N"; 
          ["LONG"] = "62.50W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Zudramdân"; 
      ["PROGRESS"] = "Discover Zudramdân"; 
      ["LORE"] = "Zudramdân may not be as formidable as Annâk-khurfu, but the dwarves' northern camp allows them some modicum of safety in the long fight to retake their home."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "36.80N"; 
          ["LONG"] = "64.65W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Grálinvarth"; 
      ["PROGRESS"] = "Discover Grálinvarth"; 
      ["LORE"] = "The rushing waterfalls of the Greylin River drown out even the loudest of sounds at Grálinvarth. From this vantage point, one can easily spot the Rushgate and Annâk-khurfu, as well as glimpse the valley of Misthallow on a clear day."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "35.32N"; 
          ["LONG"] = "58.45W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Gates of Gundabad"; 
      ["PROGRESS"] = "Discover the Gates of Gundabad"; 
      ["LORE"] = "Crude constructions deface the Gates of Gundabad, a mocking reminder of the dwarves' losses and defeats. One might wonder what else the Orcs have done to further corrupt the former dwarf-kingdom past this foreboding threshold."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "38.07N"; 
          ["LONG"] = "68.43W"; 
        }; 
      }; 
      };
  };
  -- The War of Three Peaks / Discovery: Shakalush, the Stair Battle
  [1879411151] = {
      [1] = {
      ["NAME"] = "Bagûd-mekhem"; 
      ["PROGRESS"] = "Discover the entrance to Shakalush, the Stair Battle"; 
      ["LORE"] = "On the eastern side of Gundabad, there is a small entrance known as Bagûd-mekhem. Led by Zhurmat, riding the mighty Groz-and-Ulk, this army poses a grave threat to the dwarf-forces being assembled outside."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "39.68N"; 
          ["LONG"] = "66.37W"; 
        }; 
      }; 
      };
  };
  -- Elderslade / Warg-slayer of Elderslade (Advanced)
  [1879411171] = {
      [1] = {
        "Complete the deed 'Warg-slayer of Elderslade'";
      };
      [2] = {
        "Defeat Wargs in Elderslade - Where the forces of darkness go, Wargs follow. Into the hills and caves of Elderslade they have burrowed, their ravenous appetite never satiated. Before the dwarf-forces can push forward, the threat of the ferocious beasts must be removed.";
      };
  };
  -- Elderslade / Hobgoblin-slayer of Elderslade (Advanced)
  [1879411172] = {
      [1] = {
        "Complete the deed 'Hobgoblin-slayer of Elderslade'";
      };
      [2] = {
        "Defeat hobgoblins in Elderslade - Hobgoblins. Meaner, fiercer, crueller… smarter than their Orc or goblin cousins. It is they who are often responsible for organizing the forces of the Enemy. Their malice is made all the worse for how cunning they can be.";
      };
  };
  -- Elderslade / Angmarim-slayer of Elderslade (Advanced)
  [1879411173] = {
      [1] = {
        "Complete the deed 'Angmarim-slayer of Elderslade'";
      };
      [2] = {
        "Defeat Angmarim in Elderslade - Though their realm has fallen, followers of Angmar have allied with the Orcs of Gundabad and seek to reform their kingdom of old. Their priests and sorcerers weave foul enchantments and delight in torture and destruction.";
      };
  };
  -- Elderslade / Enemy Encampments of Elderslade
  [1879411174] = {
      [1] = {
      ["NAME"] = "Howlers' Notch"; 
      ["PROGRESS"] = "Discover Howlers' Notch"; 
      ["LORE"] = "The rocky outcrops and hidden caves of the hills of Elderslade make for a perfect location for Warg dens. The ground is littered with bones and the weapons of those who tried and failed against the beasts.\n\nA foul odour permeates the air, and the rumble of low growls can be heard in the distance."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "35.75N"; 
          ["LONG"] = "62.58W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Malkorlash"; 
      ["PROGRESS"] = "Discover Malkorlash"; 
      ["LORE"] = "Squatting amidst sun-bleached bones of ancient worms, Malkorlash grants the hobgoblins control of both the nearby river and roads. The encampment also serves to hamper passage through the hills to the Wyrmsgráf River on the eastern side. The hobgoblin and dragon-kin filled passage is from whence Malkorlash, 'mountain gap,' gains its name."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "40.79N"; 
          ["LONG"] = "62.76W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Hanksar-mokh"; 
      ["PROGRESS"] = "Discover Hanksar-mokh"; 
      ["LORE"] = "Skulking in the shadows of Gundabad's great walls, Hanksar-mokh is a vile nest of Orcs. About the bone piles and hide tents, ancient dwarf-made structures lie in ruins, giving a hint of former glory. Rough scaffolding affords the goblin-kind the ability to swarm up and down the walls without having to use Gundabad's huge staircases."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "37.59N"; 
          ["LONG"] = "68.29W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Bagûd-mekhem"; 
      ["PROGRESS"] = "Discover Bagûd-mekhem"; 
      ["LORE"] = "The air about Bagûd-mekhem is unnaturally cold, with whipping winds cutting through all but the thickest furs and leathers. Ramshackle scaffolding and rough high walls have been erected about the northern walls of Gundabad. Orcs, goblins, and things even more feared swarm between walls of wood and stone."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "39.68N"; 
          ["LONG"] = "66.37W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Dûn Traikh"; 
      ["PROGRESS"] = "Discover Dûn Traikh"; 
      ["LORE"] = "Dûn Traikh bears testament to how far the Angmarim have pushed into Elderslade, and for how long they have enjoyed free reign in the lands of the dwarves. Though their realm has fallen, there are those within the walls of Dûn Traikh who strive to bring back the kingdom the Witch King of Angmar once begot."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "36.19N"; 
          ["LONG"] = "68.10W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Caivád Sâr"; 
      ["PROGRESS"] = "Discover Caivád Sâr"; 
      ["LORE"] = "Dark and looming, the spire of Caivád Sâr is where the Angmarim come to engage in ritual, arcane arts, and torture. Caivád Sâr provides a line of defence along the eastern road, housing numerous deadly forces. Its tower thrusts up to the heavens, a grasping claw from which enemies can be spotted miles away."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "38.51N"; 
          ["LONG"] = "64.65W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Kulûg-mokh"; 
      ["PROGRESS"] = "Discover Kulûg-mokh"; 
      ["LORE"] = "Skulking in the shadows of Gundabad’s great walls and twin to Hanksar-mokh, Kulûg-mokh too is a vile nest of Orcs. About the bone piles and hide tents, ancient dwarf-made structures lie in ruins, giving a hint of former glory. Rough scaffolding affords the goblin-kind the ability to swarm up and down the walls without having to use Gundabad's huge staircases."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "38.32N"; 
          ["LONG"] = "68.04W"; 
        }; 
      }; 
      };
  };
