  -- Swanfleet & Cardolan / Perils of Swanfleet
  [1879450861] = {
      [1] = {
      ["NAME"] = "Howlingstones"; 
      ["PROGRESS"] = "Find the Howlingstones"; 
      ["LORE"] = "Wolves have lived at Howlingstones for as long as the people of Mossward can remember, but they generally do not stray too near to the outer palisade. That has changed in recent nights, however, and now the town guards have seen lupine eyes staring at them from the darkness with unsettling frequency."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "61.31S"; 
          ["LONG"] = "33.38W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Radlaw"; 
      ["PROGRESS"] = "Find Radlaw"; 
      ["LORE"] = "No one knows for sure when the ruffians came to Swanfleet, but it seems to the Stoors that the outlaw settlement of Radlaw was constructed almost overnight. Now it is not safe for most people to wander the Stoor-vales without concern, for the ruffians of Radlaw are always eager for the chance to steal coin and valuable goods from the unwary."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "59.73S"; 
          ["LONG"] = "29.29W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Fangsettle"; 
      ["PROGRESS"] = "Find Fangsettle"; 
      ["LORE"] = "The Wadewater is full of dangers, but few places within the marsh are quite as threatening as Fangsettle, where the avanc build their nests. Only the Dunlendings of nearby Lhan Garan are comfortable adventuring near this spawning ground, and even their best scouts try not to stray too near without grave need."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "54.73S"; 
          ["LONG"] = "30.46W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Bloodhollow"; 
      ["PROGRESS"] = "Find Bloodhollow"; 
      ["LORE"] = "Piles of discarded bones and the carcasses of long-dead prey mark the warg-dens of Bloodhollow, a dangerous place even the highly-skilled Dunlending warriors of Lhan Garan try to avoid without need. But there is on occasion such a need: the training of new scouts requires they be tested by dangerous circumstances and threatening foes, and what might better satisfy those conditions than the wargs who stalk Bloodhollow?"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "56.83S"; 
          ["LONG"] = "21.63W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Cobshollow"; 
      ["PROGRESS"] = "Find Cobshollow"; 
      ["LORE"] = "The gloom-web spiders that inhabit Cobshollow brook no intrusion by the Stoors who live nearby, but the folk of Glyn Helyg and Clegur learned long ago not to venture beneath the web-covered trees of this place, and the people of Lintrev stay mainly by their own farms."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "65.49S"; 
          ["LONG"] = "26.09W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Sharmokal"; 
      ["PROGRESS"] = "Find Sharmokal"; 
      ["LORE"] = "An Uruk raiding-party has established a camp not far from the Old South Road, where stands the wreckage of an Elf-tower. For what purpose was the tower built, in a past Age? The Uruks know not, and the Elves who might remember wish not to say. Now this place is Sharmokal, and it is not safe for travellers to come too near."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "60.39S"; 
          ["LONG"] = "22.32W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Caras Gelebren"; 
      ["PROGRESS"] = "Find Caras Gelebren"; 
      ["LORE"] = "The great Elf-smith Celebrimbor built the city where he would fashion his legacy at the junction of the rivers Sirannon and Glanduin. Caras Gelebren, the Silver Bastion, was a place of beauty and learning for much of the Second Age, but it was not to last. Hidden beneath a fair guise, evil came to Caras Gelebren, and Celebrimbor was deceived. Ensnared by his pride and his lust for secret knowledge, the Elf-smith nearly broke the world.\n\nWhen Sauron brought war to Eregion in the aftermath of Celebrimbor's folly, the citadel was destroyed and all memory of its peaceful days forgotten. There would be triumph in the years that followed, but beneath it all the Elves remember the foundation of shame on which it was built, and they mourn."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "53.62S"; 
          ["LONG"] = "20.92W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Tham Lasgol"; 
      ["PROGRESS"] = "Find Tham Lasgol"; 
      ["LORE"] = "The trees have claimed Tham Lasgol. It is a fate the Elves would not have mourned, but something has drawn wood-trolls to the once-beautiful site, and now it is a place of danger."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "49.30S"; 
          ["LONG"] = "23.79W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Gwâl Cruban"; 
      ["PROGRESS"] = "Find Gwâl Cruban"; 
      ["LORE"] = "The buildings that once stood here are now overgrown by reeds and haunted only by turtles."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "51.95S"; 
          ["LONG"] = "26.14W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Tham Celechir"; 
      ["PROGRESS"] = "Find Tham Celechir"; 
      ["LORE"] = "Tham Celechir, the Hall of the Swift River, was one of the last sites to stand against the armies of Sauron when he brought war to Eregion in the Second Age. Many Elves perished both within and without its walls, and evidence of their final stand can still be found in the debris that litters the once-proud ruin."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "45.56S"; 
          ["LONG"] = "19.45W"; 
        }; 
      }; 
      };
  };
  -- Swanfleet & Cardolan / Dwellers of Old Swanfleet
  [1879450862] = {
      [1] = {
      ["NAME"] = "Corner Stone"; 
      ["PROGRESS"] = "Discover an old cornerstone"; 
      ["LORE"] = "These old stones may have borne witness to Sauron’s onslaught, but they still hold fast to happier memories. Weddings, personal centenaries, and ceremonies of all kinds took place in this once-elegant pavilion."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "53.11S"; 
          ["LONG"] = "20.83W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Curious Pendant"; 
      ["PROGRESS"] = "Discover a curious pendant"; 
      ["LORE"] = "'My love, if you are reading this, then you have succeeded at my little treasure hunt and claimed the prize! I had this necklace made to your tastes. I look forward to seeing you wear it.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "55.86S"; 
          ["LONG"] = "19.32W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Engraved Stone"; 
      ["PROGRESS"] = "Discover an engraved stone"; 
      ["LORE"] = "There are carvings in the stone to mark each time this structure was renovated. The oldest numbers are impossible to decipher, and the most recent numbers date back to a time that precious few remember."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "59.08S"; 
          ["LONG"] = "21.04W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Well-used Fishing Rod"; 
      ["PROGRESS"] = "Discover a well-used fishing rod"; 
      ["LORE"] = "The hook dropped into the water with a gentle splash. The lone hobbit dipped his toes into the water, deeming its temperature 'refreshingly brisk' instead of 'horribly cold.'\n\n'I could get used to this,' he said to no one in particular.\n\nAnd so he did, fishing by the mill every Thursday evening, almost every week for the rest of his life. The only change in his routine was the addition of some company as the years carried on."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "62.49S"; 
          ["LONG"] = "26.21W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Cache of Old Notes"; 
      ["PROGRESS"] = "Discover a cache of old notes"; 
      ["LORE"] = "You recover notes from scholars and conservationists of yesteryear. They would be pleased to know the turtles of the Wadewater are thriving. Perhaps, a touch too much."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "51.84S"; 
          ["LONG"] = "25.98W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Collection of Poetry"; 
      ["PROGRESS"] = "Discover a collection of poetry"; 
      ["LORE"] = "You find an improbably well-preserved stash of paper, upon which are written several drafts of poems in flowing script.\nOne page contains the following phrases, each one struck through with the stroke of an angry quill:\nUnder the eaves of wine-red holly\ncrimson holly\nsunset-hued holly\nscarlet holly\nruby-red holly\nholly-coloured holly\n\nAnd finally, 'Underneath the eaves of holly'\nNo attribution or claim of authorship can be found."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "49.03S"; 
          ["LONG"] = "23.71W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Rusted Dagger"; 
      ["PROGRESS"] = "Discover a rusted dagger"; 
      ["LORE"] = "The thief passed the coin between his fingers, a little trick he learned from one of his many mentors.\n'It is bold of you to flaunt ill-gained goods so openly,' said a voice from behind the thief.\nFailing to hide his surprise, the thief spun on his heel. He saw a woman dressed in clothes that looked like they had been stewing in the Wadewater for days. How long had she been following him? \n'Oh this?' The thief held the gold aloft and donned an innocent smile.\n'This was just a bit of good luck, nothing more. No thieves here, unless you’re meaning to take this from me.' His free hand drifted towards the dagger at his side.\n'I have repaid your victim with coin from my own purse,' she said, ignoring his lie.\n'I do not intend to take that coin from you. I do not know you, nor your needs. But there is honest work to be had in Mossward. Prey upon those who travel this road at your own peril.'\nThe thief sneered.\n'I will not be bossed around by the likes of you!'\nThe thief went to draw his dagger, but the Ranger, as he would one day come to know her as, was upon him in an instant. She parried his feeble stab and disarmed him, sending the blade clattering to the ground. The thief felt the bite of cold steel against his neck, and he froze.\n'The only reason I am giving you this chance is that you did not harm the woman from whom you stole.'\nShe withdrew her blade, and the thief's hands snapped to his neck, checking for blood. He found none. By the time he recovered himself, the Ranger's back was to him. She was walking away.\nHe looked to where his dagger had fallen, then to the Ranger, and decided to do the same."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "58.65S"; 
          ["LONG"] = "34.54W"; 
        }; 
      }; 
      };
  };
