      [11] = {
      ["NAME"] = "Hove Farm"; 
      ["PROGRESS"] = "Explore Hove Farm"; 
      ["LORE"] = "Though not quite as established as their neighbours at Scurloc Farm, the Hove family has maintained a hardscrabble livelihood on their own small farm. In recent days, however, the family has been driven out by goblin raiders from the north."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "42.27S"; 
          ["LONG"] = "36.79W"; 
        }; 
      }; 
      };
      [12] = {
      ["NAME"] = "Tharbad"; 
      ["PROGRESS"] = "Explore Tharbad"; 
      ["LORE"] = "Like the ebb and flow of the Gwathló, the fortunes of Tharbad have fallen, risen, and fallen again throughout the centuries. Built long ago by the Númenóreans as a settlement and ford, its bridges, dikes, and dams have been destroyed and rebuilt numerous times.\n\nThanks to its position alongside the river and the North-South Road, most trade between the kingdoms of Arnor and Gondor passed through Tharbad. As the burghers of the city grew richer, the Dúnedain undertook to deepen the channel at the ford, allowing for ships of greater draught to pass. The fens and waterways of Swanfleet were dredged and drained, with extensive dikes built to support nearby farmlands.\n\nTharbad grew grander and more prosperous through trade with Gondor, the Elves, and the dwarves. But its enemies were many, and the city was often ravaged. Each time it was destroyed, the city clawed its way back, its leaders repairing, reforging, and renewing the causeway. However, when the Great Plague swept across Cardolan, its rulers could no longer keep up with the needed repairs.\n\nTharbad met its final demise slowly, as the elements battered the weakened structures. Finally, after the Fell Winter, a sudden thaw created a rushing wall of water that decimated the last bits of the crossings over the Gwathló and ruined the Great Bridge once and for all.\n\nNow the ruined city clings to the banks of a river whose hungry currents carry away more and more of its jagged remains every year."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "56.53S"; 
          ["LONG"] = "38.26W"; 
        }; 
      }; 
      };
      [13] = {
      ["NAME"] = "Nagenstones"; 
      ["PROGRESS"] = "Explore Nagenstones"; 
      ["LORE"] = "The name of this once luxuriant home, surrounded on each side by the flowing waters, has been lost to time. Perhaps its marbled floors once knew the delicate whisper of slippered feet and fine silks, but now its walls crumble as the claws of Wargs click and clack on the cold floors. Folk nearby refer to it now as Nagenstones."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "47.17S"; 
          ["LONG"] = "32.37W"; 
        }; 
      }; 
      };
      [14] = {
      ["NAME"] = "Wylvenclove"; 
      ["PROGRESS"] = "Explore Wylvenclove"; 
      ["LORE"] = "The rocky outcrop of Wylvenclove hosts the dens of a formidable wolf-pack which prowls the rolling hills and barrows of Ruddymore and Tyrn Gorthad."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "46.15S"; 
          ["LONG"] = "48.76W"; 
        }; 
      }; 
      };
  };
  -- Swanfleet & Cardolan / The Ravaging of Cardolan
  [1879450926] = {
      [1] = {
      ["NAME"] = "Oath Plaque"; 
      ["PROGRESS"] = "Discover the Oath Plaque"; 
      ["LORE"] = "Though worn and weathered by time, you are able to make out a few words inscribed upon this plaque. They seem to allude to the oaths that were sworn here hundreds of years ago, when the Hill-folk were forced to submit to Dúnedain kings."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "53.47S"; 
          ["LONG"] = "53.47W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "The Stone Seat"; 
      ["PROGRESS"] = "Discover the Stone Seat"; 
      ["LORE"] = "The stone walls of this throne room were once decorated with rich tapestries, and lush carpets lined the floors. From here ruled the princes, and one regent-princess, of Cardolan."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "39.60S"; 
          ["LONG"] = "50.63W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Deadmount Obelisk"; 
      ["PROGRESS"] = "Discover the Deadmount Obelisk"; 
      ["LORE"] = "Though weathered by time, you can make out faint writing on the large obelisk. It speaks of Artandil and Malgun, kings who met atop this hill, and who felled each other with simultaneous fatal blows.\n\nThence fell Artandil and Malgun…\n\nDread thorn pierces heart,\nWar branch striketh eye.\nRaven wine fast streaming,\nDeadmount corpse heavy.\nBattle swellers wholly slaughtered,\nForest slinkers hunger-appeased."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "44.33S"; 
          ["LONG"] = "29.22W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Ashmound Memorial"; 
      ["PROGRESS"] = "Discover the Ashmound"; 
      ["LORE"] = "This site is a memorial to the victims of the Great Plague of 1636. Nearly all occupants of Tharbad, Dol Ernil, and Gond Orchal succumbed to the plague, their bodies requiring burning instead of the usual barrow internment. Fearful of the sickness passing to the living, the bodies were burned in huge pyres without the usual ceremonies. It is said that the sky above Cardolan was grey and that ash fell for days upon the land.\n\nThe ashes of the victims were gathered and transported here, mixed together and dumped by the grieving survivors, who then piled stones atop the mound, in hopes of keeping angry spirits at rest. There is no record of the names of the dead, for they were too many in number, and most of those who put the bodies to the torch fell themselves to the illness."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "44.08S"; 
          ["LONG"] = "51.72W"; 
        }; 
      }; 
      };
      [5] = {
        "Complete the quest 'The Deciphered Scroll' (Discover the Scroll of Luilloth)";
      };
      [6] = {
      ["NAME"] = "Levee Plaque"; 
      ["PROGRESS"] = "Discover the Levee Plaque"; 
      ["LORE"] = "Carvings on this ancient stonework speak of Prince Amlaith, first born son of King Eärendur, rebuilding the levees in 777."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "56.70S"; 
          ["LONG"] = "37.36W"; 
        }; 
      }; 
      };
  };
  -- Swanfleet & Cardolan / Inhabitants of the Vanished Realm
  [1879450927] = {
      [1] = {
      ["NAME"] = "Stonecrop Encampment"; 
      ["PROGRESS"] = "Explore Stonecrop Encampment"; 
      ["LORE"] = "North-west of the crumbling ruins of Tharbad, a band of folk from the town of Bree have made a temporary settlement. Led by Burl Stonecrop, the group has come to scout Cardolan and determine whether there is room in this land for outward expansion. Stonecrop's folk have been rebuffed from Tharbad by the Orcs that have already made their way into the city, but the stubborn Bree-landers have not yet given up on their plan."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "54.29S"; 
          ["LONG"] = "40.13W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Gerwyn's Convoy"; 
      ["PROGRESS"] = "Explore Gerwyn's Convoy"; 
      ["LORE"] = "After being waylaid by bandits out of Andrath, Gerwyn's Convoy circled its waggons and set up a temporary camp-site to make repairs, replenish supplies, and decide whether they should continue their journey south into Cardolan, searching for land upon which they might settle."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "37.65S"; 
          ["LONG"] = "49.80W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Sírlond"; 
      ["PROGRESS"] = "Explore Sírlond"; 
      ["LORE"] = "Elves of Rivendell have set up a temporary camp-site across the river from Caranost, which they have dubbed Sírlond. Perched high above the roaring river and amidst the ancient ruins, they keep a wary watch upon the Orcs who now reside within the ruins of the crumbled fort."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "45.04S"; 
          ["LONG"] = "39.38W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Herne"; 
      ["PROGRESS"] = "Explore Herne"; 
      ["LORE"] = "The town of Herne sits at the meeting of the old roads south-west of Caranost. Settled long ago by folk out of Bree, it grew swiftly into a trading settlement which might eventually have rivalled Bree-town had calamity not continued to visit the land in the years that followed."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "49.93S"; 
          ["LONG"] = "44.84W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Scurloc Farm"; 
      ["PROGRESS"] = "Explore Scurloc Farm"; 
      ["LORE"] = "The Scurluc family has tamed the countryside here, establishing a productive farm for several decades. Their success has been threatened in recent months by goblin raiders and an increase in nearby banditry."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "43.50S"; 
          ["LONG"] = "33.58W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Sarn Ford"; 
      ["PROGRESS"] = "Explore Sarn Ford"; 
      ["LORE"] = "The Baranduin runs deep and wide, with few natural opportunities for crossing. One of these is at Sarn Ford, where stony shallows form a causeway, allowing for traffic of foot, hoof, and wheel. But the crossing can be dangerous, the rocks slippery, and the river fickle in its flow."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "47.77S"; 
          ["LONG"] = "56.24W"; 
        }; 
      }; 
      };
  };
