      [2] = {
      ["NAME"] = "Adder's Tooth"; 
      ["PROGRESS"] = "Find adder's tooth"; 
      ["LORE"] = "The oozing sap of adder's tooth causes huge and painful blisters on any exposed skin unlucky enough to brush against its stem. When burned, smoke from this plant has been known to cause blindness."; 
      ["POINTS"] = {
