      [3] = {
      ["NAME"] = "Wargsbite"; 
      ["PROGRESS"] = "Find wargsbite"; 
      ["LORE"] = "The bright, sweetly flavoured berries of wargsbite are a tempting treat. However, even a single bite of the fruit will soon strike one down. Afflictions start with hallucinations and convulsions, and work up to a mouthful of frothing foam which soon chokes out any and all attempts at gasping for breath."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "72.15N"; 
          ["LONG"] = "32.26W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Festerfoul"; 
      ["PROGRESS"] = "Find festerfoul"; 
      ["LORE"] = "The deadly effects of the noxious spores of festerfoul do not make themselves apparent right away. Rather, it may take weeks or months for the victim to suddenly, and most painfully, succumb to its poisonous toxins."; 
      ["POINTS"] = {
