  -- Eastern King's Gondor / Stragglers and New Threats in Lossarnach
  [1879464436] = {
      [1] = {
      ["NAME"] = "Ost Norhír"; 
      ["PROGRESS"] = "Find Ost Norhír"; 
      ["LORE"] = "The ruin of Ost Norhír stands atop the hill overlooking the river south of the Harlond, but now it is inhabited only by wildlife. When the people departed to rebuild their lives in the aftermath of the war, the beasts moved back in to make homes of their own."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "75.65S"; 
          ["LONG"] = "21.20W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Galdir's Dell"; 
      ["PROGRESS"] = "Find Galdir's Dell"; 
      ["LORE"] = "The encampment that once stood in Galdir's Dell is now burned and unrecognizable. Wargs pad among the scorched wooden structures, and their howls linger on the breezes that sweep over the river."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "77.14S"; 
          ["LONG"] = "21.43W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Aegollant"; 
      ["PROGRESS"] = "Find Aegollant"; 
      ["LORE"] = "The tents of the Haradrim remain at Aegollant, despite the defeat of the Black Serpent at the Battle of Pelennor Fields, but they are now home mostly to brigands and others who hold villainy in their hearts."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "78.64S"; 
          ["LONG"] = "23.07W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Erui Delta"; 
      ["PROGRESS"] = "Find the Erui Delta"; 
      ["LORE"] = "The River Erui empties into the Anduin here, and avanc prowl among the reedy banks, threatening unwary travellers."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "80.53S"; 
          ["LONG"] = "24.19W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Taustrok"; 
      ["PROGRESS"] = "Find Taustrok"; 
      ["LORE"] = "Remnants of the Morgul-host, scattered after the Battle of the Pelennor Fields, have begun to gather in alarming numbers in a camp they call 'Taustrok.' Within dank caves they burrow into the mountainside, threatening to spill over and become a threat to the nearby town of the Harlond."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "70.72S"; 
          ["LONG"] = "22.65W"; 
        }; 
      }; 
      };
  };
  -- Eastern King's Gondor / Reclaiming Lossarnach
  [1879464437] = {
      [1] = {
      ["NAME"] = "Arnach"; 
      ["PROGRESS"] = "Find Arnach"; 
      ["LORE"] = "Lord Forlong, the ruler of Lossarnach, kept a hall in the village of Arnach until he rode to Minas Tirith during the War of the Ring. He perished in the fighting on the Pelennor and now his hall stands empty, the people of Arnach doing the best they can to go on without their much-loved lord. Arnach remains a bustling settlement for merchants and craftsmen, but the memory of the Haradrim attacks during the previous months remains painful."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "76.55S"; 
          ["LONG"] = "24.40W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Imloth Melui"; 
      ["PROGRESS"] = "Find Imloth Melui"; 
      ["LORE"] = "Imloth Melui, the Vale of Sweet Flowers, is the home of Lady Vanyalos, sister of the Steward Denethor and wife of Forlong, Lord of Lossarnach. Both of these men perished during the war, one inside the walls of the White City and the other without, but the wounds of their passing lie especially deep upon Vanyalos, for she dreamed it would happen and feels the burden of failing to prevent it.\n\nImloth Melui provides many of the healers who work at the Houses of Healing in Minas Tirith, including the woman Ioreth, who knows a little about an impressive array of things, and an impressive amount about very little."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "73.20S"; 
          ["LONG"] = "24.79W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Nan Harlond"; 
      ["PROGRESS"] = "Find Nan Harlond"; 
      ["LORE"] = "The fields and farms of Nan Harlond stand on either side of the road below the south-harbour of Gondor, no longer threatened by the armies of Sauron but still endangered by occasional foes left behind by their defeated allies. The natural beauty of Lossarnach fights to emerge following the War of the Ring, and the flowers here are a testament to its resilience."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "74.29S"; 
          ["LONG"] = "21.04W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Rammas Echor"; 
      ["PROGRESS"] = "Find the Rammas Echor"; 
      ["LORE"] = "The great wall that is the Rammas Echor encircles Minas Tirith and the Pelennor Fields. During the war, the wall was breached in several places and the forces of Sauron streamed through to lay siege to the White City. Now, dwarves and Gondorian labourers work to repair the damage and shore up the defences once again, though all hope the Rammas will not be needed again for many years."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "72.14S"; 
          ["LONG"] = "18.75W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "The Harlond"; 
      ["PROGRESS"] = "Find the Harlond"; 
      ["LORE"] = "The Harlond was held by Orcs of Mordor in the days before the Battle of Pelennor Fields, and the creatures burned as many of the Gondorian ships as they could. When Corsair ships flying black sails came up the river from the south, the Orcs were taken by surprise when the banner of the King was raised, revealing the vessels to be commanded by Aragorn and the allies of Gondor. Their arrival on the field of battle proved instrumental in the defence of Minas Tirith and the defeat of Sauron's forces.\n\nToday, the folk of Gondor and dwarves from the White Mountains work to repair and rebuild the south-harbour, hoping that trade and goods will once again flow freely upon the river to ports both near and far."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "72.72S"; 
          ["LONG"] = "20.01W"; 
        }; 
      }; 
      };
  };
  -- Eastern King's Gondor / Reclaiming Upper Lebennin
  [1879464470] = {
      [1] = {
      ["NAME"] = "Minlos"; 
      ["PROGRESS"] = "Find Minlos"; 
      ["LORE"] = "The beacon of Minlos is the nearest to Minas Tirith, and was seized by Haradrim raiders during the war as they attempted to move against the village of Arnach. Now the beacon has been extinguished and folk of nearby farms hope it will remain unlit for many years, a signal the danger has passed."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "76.83S"; 
          ["LONG"] = "25.96W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Halach"; 
      ["PROGRESS"] = "Find Halach"; 
      ["LORE"] = "The small harbour of Halach was abandoned to the Haradrim during the war, but the defeat of Sauron has allowed the townsfolk to return and begin the long process of rebuilding their lives and homes."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "82.26S"; 
          ["LONG"] = "26.21W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Glaniath"; 
      ["PROGRESS"] = "Find Glaniath"; 
      ["LORE"] = "The small farming community of Glaniath was threatened by Haradrim raiders during the war, and now the people try to pick up the pieces of their lives in the aftermath. Some folk here believe Sirgon's captivity by the Haradrim has made him unfit to rule and his son Faltharan should become Lord of Lebennin in his stead."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "80.62S"; 
          ["LONG"] = "29.70W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Tumladen"; 
      ["PROGRESS"] = "Find Tumladen"; 
      ["LORE"] = "Tumladen is the great refuge of Gondor, similar in kind to Helm's Deep in the kingdom of Rohan. During the war, many folk took shelter in Tumladen, including one of Steward Denethor's prickly sisters, the opinionated Lady Terenis. Much to the relief of Captain Imladir, who is responsible for the defence of Tumladen, the Lady Terenis has now returned to Minas Tirith. The sanctuary is no longer crowded with displaced folk of Gondor."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "76.84S"; 
          ["LONG"] = "29.35W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Pelargir"; 
      ["PROGRESS"] = "Find Pelargir"; 
      ["LORE"] = "The port city of Pelargir was the site of the pivotal battle against the Corsairs of Umbar during the War of the Ring, when Aragorn commanded the Army of the Dead to seize their ships. Balakhôr the Scourge met his end aboard his grand vessel, the Night-jewel, and it is hoped his death will spell the end of the threat posed by the Heirs of Castamir.\n\nThe Gondorian fleet is in shambles following the War of the Ring, and it will be the task of Sirgon, Lord of Lebennin, to rebuild the kingdom's ships and sea-power as quickly as possible. To that end, the city of Pelargir is filled with the sound of hammers and axes at all hours of the day and night."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "84.01S"; 
          ["LONG"] = "33.18W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Sirthanc"; 
      ["PROGRESS"] = "Find Sirthanc"; 
      ["LORE"] = "The beacon of Sirthanc was lit during the war to summon warriors to defend Minas Tirith, but it is now quenched. If the fortune of Gondor holds, it will remain extinguished for many years. It was at Sirthanc that Lord Sirgon was rescued from the captivity of the Haradrim, and now some of his folk believe he should be allowed to step down as Lord of Lebennin so he may heal the wounds of his mind and body."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "79.35S"; 
          ["LONG"] = "31.96W"; 
        }; 
      }; 
      };
  };
  -- Eastern King's Gondor / Stragglers and New Threats in Upper Lebennin
  [1879464471] = {
      [1] = {
      ["NAME"] = "Grafeleg"; 
      ["PROGRESS"] = "Find Grafeleg"; 
      ["LORE"] = "The cave of Grafeleg is tucked into the mountains behind Tumladen, and the bears that dwell within have generally not troubled the residents of the refuge, the folk of Gondor reciprocating in kind. However, with many more folk dwelling behind the walls of Tumladen while the war raged, tensions with those living nearby have been inflamed."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "74.48S"; 
          ["LONG"] = "30.54W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Lhingar"; 
      ["PROGRESS"] = "Find Lhingar"; 
      ["LORE"] = "The spiders of Lhingar were not stymied by the waging of the War of the Ring, and they were not hindered by its ending. They creep still among the trees, spinning webs to catch their prey and feasting upon any who stray too near their den."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "74.77S"; 
          ["LONG"] = "26.37W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Sadúkh's Camp"; 
      ["PROGRESS"] = "Find Sadúkh's Camp"; 
      ["LORE"] = "In the aftermath of the War of the Ring, some of the Corsairs fled into the wild and sought to seize victory from their apparent defeat. This is the camp of Sadúkh, who believes he is the one to unify the Corsairs beneath his banner."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "77.42S"; 
          ["LONG"] = "27.79W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Múshex's Camp"; 
      ["PROGRESS"] = "Find Múshex's Camp"; 
      ["LORE"] = "After the war's ending, some of the Corsairs fled into the wild in order to regroup. This is the camp of Múshex, who seeks to unify the Corsairs beneath his own banner."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "80.67S"; 
          ["LONG"] = "25.71W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Hárba's Camp"; 
      ["PROGRESS"] = "Find Hárba's Camp"; 
      ["LORE"] = "After their defeat at Pelargir, some of the Corsairs escaped into the wild. This is the camp of Hárba, who believes his victory is not far off."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "82.37S"; 
          ["LONG"] = "29.64W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Bukhád's Camp"; 
      ["PROGRESS"] = "Find Bukhád's Camp"; 
      ["LORE"] = "After their defeat at Pelargir, some of the Corsairs escaped into the wild. This is the camp of Bukhád, who is certain that his warriors will have victory if they can recover their strength."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "81.39S"; 
          ["LONG"] = "31.84W"; 
        }; 
      }; 
      };
  };
  -- Eastern King's Gondor / Reclaiming Lower Lebennin
  [1879464488] = {
      [1] = {
      ["NAME"] = "Erynos"; 
      ["PROGRESS"] = "Find Erynos"; 
      ["LORE"] = "The settlement of Erynos was the site of one of the stranger occurrences of the war, when a number of Corsair raiders were discovered outside the walls of town, apparently drowned. Some folk believe this was the work of the Five Sisters of Lebennin, river-maidens thought to protect the lands through which their rivers flow, but some say they are only figures of myth.\n\nToday the folk of Erynos work to restore their lives and aid those of their neighbours who suffered during the war."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "80.08S"; 
          ["LONG"] = "32.80W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Ost Anglebed"; 
      ["PROGRESS"] = "Find Ost Anglebed"; 
      ["LORE"] = "The large city of Ost Anglebed is home to the keepers of the beacon of Amon Anglebed, which was lit during the War of the Ring. Unlike the other beacons of Gondor, the beacon here remains lit despite the arrival of the King's peace. Now the guards maintain a vigil over the townsfolk, fearful that some allies of disloyal Malthellim may think to continue his work and turn control of the town over to foes of Gondor."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "78.98S"; 
          ["LONG"] = "39.14W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Malbarth"; 
      ["PROGRESS"] = "Find Malbarth"; 
      ["LORE"] = "The small village of Malbarth escaped much of the fighting during the war, but tidings from other areas of Gondor filled the townsfolk here with trepidation and fear that their homes would not remain safe for long. Even now there are whispers that some Corsairs fled from the battle at Pelargir and hide now in the wilderness, awaiting their chance to seize the town."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "80.14S"; 
          ["LONG"] = "42.38W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Linhir"; 
      ["PROGRESS"] = "Find Linhir"; 
      ["LORE"] = "The city of Linhir spans the River Gilrain, and during the War of the Ring the sky here was darkened by foul craft of Sauron. The sons of Comeldir organized the defences, and when the fighting at last was ended, the people stood strong, less divided than their city. Today, with the threat of war behind them and the skies bright and clear once again, the folk of Linhir have returned to their lives."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "81.41S"; 
          ["LONG"] = "45.43W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Sarnhad"; 
      ["PROGRESS"] = "Find Sarnhad"; 
      ["LORE"] = "This small village on the River Serni escaped most of the fighting during the war, but the report of Corsairs and half-trolls attacking other nearby towns filled the residents with dread, as did the darkened skies brought on by the Dawnless Day. Today, the folk of Sarnhad seek to return to their ordinary lives."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "81.59S"; 
          ["LONG"] = "43.90W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Zarsatrâd"; 
      ["PROGRESS"] = "Find Zarsatrâd"; 
      ["LORE"] = "Nestled in the forest south of the dwarf-stronghold of Furukzahar, Zarsatrâd serves as an outpost for the Temámir dwarves who live now in the White Mountains. They work to transport quarried stone to various locations in Gondor, eager to help their neighbours repair and rebuild following the War of the Ring... for a reasonable price."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "77.80S"; 
          ["LONG"] = "34.56W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Furukzahar"; 
      ["PROGRESS"] = "Find Furukzahar"; 
      ["LORE"] = "The stronghold of Furukzahar is a bastion of safety for the Temámir Dwarves of the White Mountains. Under the rule of their leader Hámisar, dwarves from any clan are welcome to visit, but relations with the people of Gondor are not especially warm at the moment. Hámisar's decision to shut the doors of Furukzahar and not participate in the War of the Ring has not endeared the dwarves to the residents of Lebennin."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "70.34S"; 
          ["LONG"] = "35.35W"; 
        }; 
      }; 
      };
  };
  -- Eastern King's Gondor / Stragglers and New Threats in Lower Lebennin
  [1879464489] = {
      [1] = {
      ["NAME"] = "Lornost"; 
      ["PROGRESS"] = "Find Lornost"; 
      ["LORE"] = "The ruins of Lornost remain a sad reminder of the cruelty inflicted by the Heirs of Castamir and their Haradrim allies: when the folk of Lornost refused to surrender, they were slaughtered and the castle reduced to rubble. Now only wild beasts walk the paths of Lornost, and a cruel breeze drifts among the abandoned buildings."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "80.77S"; 
          ["LONG"] = "34.41W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Thama Aklam"; 
      ["PROGRESS"] = "Find Thama Aklam"; 
      ["LORE"] = "The war-camp of Thama Aklam was constructed during the war by Haradrim forces seeking to accomplish the aims of Mordor. With the defeat of Sauron, the war-camp has become home instead to brigands and other unsavoury types."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "80.69S"; 
          ["LONG"] = "36.55W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Hata Kebir"; 
      ["PROGRESS"] = "Find Hata Kebir"; 
      ["LORE"] = "The war-camp of Hata Kebir served as one of the primary settlements constructed by the Haradrim and Corsairs that united to threaten Lebennin and the greater lands of Gondor. In the days since the end of the war, brigands have congregated within its bounds and endanger the King's peace."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "84.53S"; 
          ["LONG"] = "37.30W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Ruins of Ethillorn"; 
      ["PROGRESS"] = "Find the Ruins of Ethillorn"; 
      ["LORE"] = "The Corsairs of Umbar burned the port of Ethillorn as part of their campaign to conquer Gondor for Sauron. Now that the war has ended the Corsairs have gone, but a darker evil has come to Ethillorn and now threatens the surrounding lands."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "83.85S"; 
          ["LONG"] = "45.62W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Orlach's Ghyll"; 
      ["PROGRESS"] = "Find Orlach's Ghyll"; 
      ["LORE"] = "Lured from the snowy peaks of the White Mountains by the sound of industry at the quarry of Aban-bazan, ferocious snow-beasts have made new dens in the woods of Lebennin. Gnawed bones and filthy carcasses lie in piles beneath the trees and among the rocks, a testament to the beasts' insatiable hunger."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "74.96S"; 
          ["LONG"] = "35.77W"; 
        }; 
      }; 
      };
  };
