      [5] = {
      ["NAME"] = "Parth Rest"; 
      ["PROGRESS"] = "Find Parth Rest"; 
      ["LORE"] = "Once the site of a deadly battleground during the war, Parth Rest was erected by the brother Herion to oversee rebuilding efforts and to organize supplies being transported through the region."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "80.19S"; 
