  -- Outer Gondor / Perils of the Langstrand
  [1879468393] = {
      [1] = {
      ["NAME"] = "Khatsûr"; 
      ["PROGRESS"] = "Find Khatsûr"; 
      ["LORE"] = "What once served as a landing for many Corsair raids remains on the shores of Hathollant as a ready reminder that the Corsairs could return in force at any moment. Now, it serves as home to stragglers and those who refused to leave."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "67.76S"; 
          ["LONG"] = "95.88W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Snarlwood"; 
      ["PROGRESS"] = "Find Snarlwood"; 
      ["LORE"] = "Filled with avanc, Snarlwood remains a bastion and home for the animals, and a readily available source of sustenance for the most daring of hunters in Langstrand."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "68.72S"; 
          ["LONG"] = "93.66W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Delugel"; 
      ["PROGRESS"] = "Find Delugel"; 
      ["LORE"] = "Throughout time this place has been avoided by many a resident of Lond Cirion, given to the cautionary tales of fantasy. Do those that dwell within claim its power by those very tales or have they existed within all along?"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "64.81S"; 
          ["LONG"] = "95.30W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Loxhall"; 
      ["PROGRESS"] = "Find Loxhall"; 
      ["LORE"] = "Once a site for travellers to find reprieve and make camp, Loxhall has long been taken over by the growing lynx population."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "66.25S"; 
          ["LONG"] = "87.85W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Springer's Close"; 
      ["PROGRESS"] = "Find Springer's Close"; 
      ["LORE"] = "Springer's Close is a place known to many residents of Barad Faen as the main concern for many travellers making their way to Iaphel and Pinnath Gelin."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "64.81S"; 
          ["LONG"] = "84.82W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Khâla Niket"; 
      ["PROGRESS"] = "Find Khâla Niket"; 
      ["LORE"] = "Long ago, the cove of Khâla Niket proved deadly for the Corsair banner-ship that sought to gain access to the unprotected lands nearby. Today, only the wreck remains, a grim reminder of the Umbari aggression that nearly spelled doom for the folk of the Langstrand."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "71.04S"; 
          ["LONG"] = "85.59W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Fleetmire"; 
      ["PROGRESS"] = "Find Fleetmire"; 
      ["LORE"] = "In their search for wood, the Corsairs have destroyed many trees and disturbed the local wild-life -- most notably the bog-lurkers."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "63.94S"; 
          ["LONG"] = "79.22W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Bel Tâkhmar"; 
      ["PROGRESS"] = "Find Bel Tâkhmar"; 
      ["LORE"] = "Having avoided the worst of the fighting during the war, the Corsairs in Anfalas remain a well-equipped threat."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "67.07S"; 
          ["LONG"] = "70.49W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Wreck of the Kêl Tezhor"; 
      ["PROGRESS"] = "Find the Wreck of the Kêl Tezhor"; 
      ["LORE"] = "Not all of the Corsairs who raided Anfalas were lucky enough to emerge with ill-gotten goods. Some found themselves at the mercy of the sea -- a peril all Corsairs are familiar with, but one that cannot be fully mastered."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "69.16S"; 
          ["LONG"] = "78.84W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Lithengris"; 
      ["PROGRESS"] = "Find Lithengris"; 
      ["LORE"] = "For those who know what they're doing, or otherwise are willing to risk a few fingers, the crabs at Lithengris are a valuable source of food. Very few people venture into the cave itself, however...."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "70.70S"; 
          ["LONG"] = "69.97W"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "Dun Ox Herd"; 
      ["PROGRESS"] = "Find the Dun Ox Herd"; 
      ["LORE"] = "The dun oxen roam the hills of Anfalas peacefully, unbothered by the sparse vegetation and arid climate of their home. Get too close, however, and you may find that a bull's horns are just as sharp as they appear to be."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "64.96S"; 
          ["LONG"] = "73.04W"; 
        }; 
      }; 
      };
  };
