  [1879468396] = {
      [1] = {
      ["NAME"] = "Barad Faen"; 
      ["PROGRESS"] = "Find Barad Faen"; 
      ["LORE"] = "A small hamlet that sits at the foot of the beacon of Barad Faen. Wanderers and travellers alike have all set foot in Barad Faen on their way to Lond Cirion and Pinnath Gelin."; 
      ["POINTS"] = {
