      [2] = {
      ["NAME"] = "Echad Lendir"; 
      ["PROGRESS"] = "Find Echad Lendir"; 
      ["LORE"] = "The Elves have run into troubles on their pilgrimage to Iaphel in Pinnath Gelin. They resolved to make a retreat upon the bluffs of the Langstrand for future travellers to rest, as the road north is ever troubled by lynx-cats and Neekerbreekers."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "67.05S"; 
          ["LONG"] = "85.61W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Tumbamálë"; 
      ["PROGRESS"] = "Find Tumbamálë"; 
      ["LORE"] = "The grove of Tumbamálë, called Strangdene by the folk who live nearby, has a reputation for mystery. Few dare pass beneath its boughs, and those who do report hearing strange noises and the sensation of being watched. Even the Corsairs who raid the coast steer clear of the grove, unless they are compelled within by a captain with a harder heart than most others."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "70.59S"; 
          ["LONG"] = "95.03W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Lond Cirion"; 
      ["PROGRESS"] = "Find Lond Cirion"; 
      ["LORE"] = "The Men of Númenor arrived in the mid-Second Age, the land was still mostly untouched. Those sea-farers made their first landfall upon the Langstrand after discovering the Bay of Belfalas, and the stronghold they built at the mouth of the mighty River Lagorduin, which they named Ciryalondë and is now known by the name Lond Cirion."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "69.35S"; 
          ["LONG"] = "89.39W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Arthiant"; 
      ["PROGRESS"] = "Find Arthiant"; 
      ["LORE"] = "The bridge of Arthiant stands as a remnant of an era long passed, when the River Hathollant was not the westernmost extent of Gondor. But as the kingdom faded, so too did its borders."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "67.16S"; 
          ["LONG"] = "94.98W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Thombad"; 
      ["PROGRESS"] = "Find Thombad"; 
      ["LORE"] = "In the months after the war, the bridge to Anfalas from Tarlang's Crown was given some much-needed repairs."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "69.84S"; 
          ["LONG"] = "66.93W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Sadrech's Camp"; 
      ["PROGRESS"] = "Find Sadrech's Camp"; 
      ["LORE"] = "While Melgobas mostly relies on fish for food and commerce, its people also rely on hunters for bones and meat."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "67.69S"; 
          ["LONG"] = "72.61W"; 
