  -- Khûd Zagin / Discovering Khûd Zagin
  [1879491605] = {
      [1] = {
      ["NAME"] = "Jirush"; 
      ["PROGRESS"] = "Find Jirush"; 
      ["LORE"] = "Jirush was once the chief town and resupply station for caravans passing south along the Road of Riches, but today it is mostly derelict, its people displaced by war and forced relocation to the mines. Some old men and women remain in Jirush, their hands kept busy with daily troubles even as their minds remember better days, long ago. The sand is slowly overtaking Jirush, and it is a common belief of those few who remain here that in a dozen years or fewer, the town will be entirely consumed by the spreading desert."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "37.26S"; 
          ["LONG"] = "79.95W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Shonith"; 
      ["PROGRESS"] = "Find Shonith"; 
      ["LORE"] = "In the language of the Avabár-kintai, the name Shonith means 'glade of peace,' and the Elves who tend this oasis in the southern reaches of the Khûd work tirelessly so it may retain that name. The Veróthi of faded Kintai grow on islands in the pool at the centre of Shonith, and others are planted around the water, an oasis of life kept separate from the desert sands... for the time being."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "45.94S"; 
          ["LONG"] = "72.50W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Tombs of Nirgambâr"; 
      ["PROGRESS"] = "Find the Tombs of Nirgambâr"; 
      ["LORE"] = "The vaults and tombs of Nirgambâr stand in a sheltered valley in the northern reaches of the Khûd, now largely buried by desert. The tombs were used by Black Númenóreans in the Third Age to house their dead, and the Khûdi say restless spirits and dangerous wights have stalked their silent halls ever since. Rumour has it these occurrences predate even the Black Númenóreans, and may have been involved in their abandonment of the site, but none still live who might say for certain."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "34.45S"; 
          ["LONG"] = "87.94W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Span of Danagír"; 
      ["PROGRESS"] = "Find the Span of Danagír"; 
      ["LORE"] = "In the language of the Shagâni, the name Danagír means 'safe path,' but the high span that bridges the River Barûg between Khûd Zagin and Imhûlar does not feel as safe as its name promises."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "37.13S"; 
          ["LONG"] = "71.77W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Menundâri-en"; 
      ["PROGRESS"] = "Find Menundâri-en"; 
      ["LORE"] = "The colossal statue Menundâri-en, the Eternal One, was sculpted during the Second Age in memory of the mighty sorcerer-king Izighûz. It was considered heretical by the Church of Barkhûsh, which attempted to destroy it, but what remains of the Eternal One can still be seen in Khûd Zagin."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "32.26S"; 
          ["LONG"] = "82.40W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Ghalbûru"; 
      ["PROGRESS"] = "Find Ghalbûru"; 
      ["LORE"] = "This valley and cavern complex among the rocky canyons in the east of the Khûd was called 'Thieves' Cut' by the residents of Jirush and their Ordâkhai occupiers. The name was adopted as a badge of honour by the varied brigands, highwaymen, and freedom fighters that now make their home here in the Cut, and they use its Shagâni name of Ghalbûru."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "37.08S"; 
          ["LONG"] = "73.83W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Western Khanâg"; 
      ["PROGRESS"] = "Find Western Khanâg"; 
      ["LORE"] = "A Khanâg serves as a resting-place for traders and their beasts on the major roads that pass through the desert, and as a meeting-place and market for local residents of the Khûd.\n\nThis Khanâg west of Jirush still bustles with moderate activity, despite the soldiers of Ordâkh stationed nearby."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "36.01S"; 
          ["LONG"] = "82.41W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Ruined Khanâg"; 
      ["PROGRESS"] = "Find Ruined Khanâg"; 
      ["LORE"] = "A Khanâg serves as a resting-place for traders and their beasts on the major roads that pass through the desert, and as a meeting-place and market for local residents of the Khûd.\n\nThis Khanâg east of Jirush is no longer active, and has become ruined and desolate. Few travel here, and of those who make the journey most have cause to regret it."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "38.58S"; 
          ["LONG"] = "76.82W"; 
        }; 
      }; 
      };
  };
