  -- Khûd Zagin / Dangers in Khûd Zagin
  [1879491607] = {
      [1] = {
      ["NAME"] = "Samârsug"; 
      ["PROGRESS"] = "Find Samârsug"; 
      ["LORE"] = "Crocodiles have taken the flood-plains south of the river for their own, and now Samârsug can only be explored by those who fear not the sharp teeth of its hostile residents."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.96S"; 
          ["LONG"] = "91.20W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Nizukhûr"; 
      ["PROGRESS"] = "Find Nizukhûr"; 
      ["LORE"] = "The sun-baked walls of this once-populous desert town mark the bounds of Nizukhûr, the 'brigands' seat.' The former residents abandoned their homes first to the Ordâkhai who served the Black Serpent, but few of those soldiers returned from the war and now the dwellings are claimed by brigands."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "36.81S"; 
          ["LONG"] = "87.99W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Ar-jirush"; 
      ["PROGRESS"] = "Find Ar-jirush"; 
      ["LORE"] = "This fortress overlooking the settlement of Jirush still hosts many soldiers of Ordâkh, both from the local garrison and those who escaped the recent Ambarûli liberation. The Ordâkhai keep watch over the road, waylaying passing travellers for the purpose of exacting heavy tolls. The cost of these tolls increases as the temperature rises, as does the threat of the Ordâkhai who collect them."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "33.97S"; 
          ["LONG"] = "80.41W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Phûrakoth"; 
      ["PROGRESS"] = "Find Phûrakoth"; 
      ["LORE"] = "The Ordâkhai presence in Khûd Zagin remains a danger to local residents, despite the heavy losses sustained by soldiers of the Great Southern Empire during the War of the Ring. The Black Serpent will not return from Gondor, but many of those who fought for him fled from the fighting before the walls of Minas Tirith, and they are made even more desperate and dangerous as they return to the lands they claim for their own."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "40.22S"; 
          ["LONG"] = "73.24W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Nu-hashâr"; 
      ["PROGRESS"] = "Find Nu-hashâr"; 
      ["LORE"] = "Crebain and carrion birds dwell among the angular structures and rocky cliffs of Nu-hashâr, sheltered from unwanted attention by the steep rise upon which the fortress of Ar-jirush overlooks the Khûd."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "32.99S"; 
          ["LONG"] = "82.23W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Anzusag"; 
      ["PROGRESS"] = "Find Anzusag"; 
      ["LORE"] = "Birds nest among the greenery of Anzusag on the cliffs high above the oasis of Shonith. From here the sands of the desert seem far away, a distant mirage."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "42.12S"; 
          ["LONG"] = "71.77W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Er-atûr"; 
      ["PROGRESS"] = "Find Er-atûr"; 
      ["LORE"] = "Er-atûr was once a fertile oasis like the others tended by the Kintai, but it is no longer a place of thriving vegetation and greenery. Now wrathful spirits whisper on the wind and Er-atûr has become a place of ill omen."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "40.80S"; 
          ["LONG"] = "81.62W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Ish Dâra"; 
      ["PROGRESS"] = "Find Ish Dâra"; 
      ["LORE"] = "The banks of the River Usâl were once green and fertile, but the Great Dearth dried out the fields and left Ish Dâra to fall into ruin and decay. Now only lizards and scorpions call this ruin home, and the Khûdi have left to find a more hospitable dwelling."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "42.47S"; 
          ["LONG"] = "87.92W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Sûr Zugub"; 
      ["PROGRESS"] = "Find Sûr Zugub"; 
      ["LORE"] = "The wind whistles through the canyons of Sûr Zugub in the southern reaches of the Khûd, where lizards and other creatures bake on the hot stones. Travellers are advised to keep to the shade provided by the high stones, for the oppressive heat threatens to end any unwise journey."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "42.40S"; 
          ["LONG"] = "78.43W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Ul Sukûd"; 
      ["PROGRESS"] = "Find Ul Sukûd"; 
      ["LORE"] = "Wights prowl among the ruins of Ul Sukûd, high above the crypts of Nirgambâr."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "32.59S"; 
          ["LONG"] = "88.62W"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "Shukabad"; 
      ["PROGRESS"] = "Find Shukabad"; 
      ["LORE"] = "The jackals of Shukabad never sleep. They remain alert and aware at all times, padding on quiet feet among the piles of bones and skulls that line their lair, eager to find the next unwary traveller who might become their next meal."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "35.54S"; 
          ["LONG"] = "85.04W"; 
        }; 
      }; 
      };
  };
