  -- Urash Dâr / Discovering Urash Dâr
  [1879491679] = {
      [1] = {
      ["NAME"] = "Ub Nishir"; 
      ["PROGRESS"] = "Find Ub Nishir"; 
      ["LORE"] = "The settlement of Ub Nishir, tucked into a narrow canyon north of the stone keep of Maurûsh, is populated mostly by brigands and highwaymen who have nowhere else to turn. By necessity they have become protectors of the few folk who remain in Urash Dâr."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.14S"; 
          ["LONG"] = "62.54W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Nêruzig"; 
      ["PROGRESS"] = "Find Nêruzig"; 
      ["LORE"] = "From this small campsite, the people who remain in Urash Dâr maintain a watch upon the newly-opened crevice at Utug-bûr behind which terrible evils lurk."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.24S"; 
          ["LONG"] = "56.42W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Ilzag Khûl"; 
      ["PROGRESS"] = "Find Ilzag Khûl"; 
      ["LORE"] = "Few alone remain at Ilzag Khûl, for evil stirs in nearby Maurûsh. Now it must become a place of safety from which your allies can strike against the foes that endanger all of Urash Dâr."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "26.60S"; 
          ["LONG"] = "61.44W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Shengarâsh"; 
      ["PROGRESS"] = "Find Shengarâsh"; 
      ["LORE"] = "In the Shagâni language, Shengarâsh means 'encampment of the rain or mist;' it is truly an appropriate name for this camp by the Falls of Ilûritu in northern Urash Dâr."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "16.61S"; 
          ["LONG"] = "62.54W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Channel of Bâdizal"; 
      ["PROGRESS"] = "Find the Channel of Bâdizal"; 
      ["LORE"] = "This great stonework was constructed by the Númenóreans when they channeled the Ikorbân River near Urash Dâr. The process took many years, but its end result broadened the waterway and made it more navigable for Númenórean ships passing inland."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "28.34S"; 
          ["LONG"] = "62.18W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Falls of Ilûritu"; 
      ["PROGRESS"] = "Find the Falls of Ilûritu"; 
      ["LORE"] = "These falls in northern Urash Dâr are beautiful and perilous, and none know what secrets they may conceal."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "13.78S"; 
          ["LONG"] = "62.73W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Ashâgir"; 
      ["PROGRESS"] = "Find Ashâgir"; 
      ["LORE"] = "Hidden deep within the gorge-lands, the clifftop fortress of Ashâgir was built into a high outcrop well above the canyon floor. Once a lift climbed to the heights, but that device has been long-since destroyed; now only precipitous paths wind slowly to the lofty entrance. The last king of Hamât sheltered within when the Great Southern Empire of Ordâkh invaded, but he commanded the destruction of the fortress rather than surrender it, and perished there. Now Ashâgir stands empty, plundered of its treasure."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "19.63S"; 
          ["LONG"] = "70.38W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Sûr Akil"; 
      ["PROGRESS"] = "Find Sûr Akil"; 
      ["LORE"] = "Sûr Akil, the north-eastern canyon through which the River Mûshid runs, means 'the gorge of woe' in the language of the Shagâni. None remember why they gave it this name, but the sensation of great evil that has settled upon this area in recent days seems justification enough."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "21.50S"; 
          ["LONG"] = "57.70W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Malgâma"; 
      ["PROGRESS"] = "Find Malgâma"; 
      ["LORE"] = "The way-station of Malgâma attracts all sorts, or at least, it would if there was still a large population remaining in the settlements of Urash Dâr. Instead, the folk who come to this small collection of buildings near Zikrum-dûl share one thing in common: their eccentricity."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "26.39S"; 
          ["LONG"] = "52.71W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Utug-bûr"; 
      ["PROGRESS"] = "Find Utug-bûr"; 
      ["LORE"] = "Recent quakes ripped open a fissure in a formerly-solid cliff face, altering the course of the river and revealing the doorstep of Utug-bûr, a stone structure kept secret for untold years. None still live who remember the making of this place, and now a sensation of great evil grips the hearts of any who approach."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "13.21S"; 
          ["LONG"] = "51.61W"; 
        }; 
      }; 
      };
  };
  -- Urash Dâr / Dangers in Urash Dâr
  [1879491680] = {
      [1] = {
      ["NAME"] = "Ushbarab"; 
      ["PROGRESS"] = "Find Ushbarab"; 
      ["LORE"] = "Tangled webs woven by the spiders that lurk at Ushbarab make travel in north-western Urash Dâr difficult, if not outright impossible."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "15.67S"; 
          ["LONG"] = "67.71W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Tûkurdul"; 
      ["PROGRESS"] = "Find Tûkurdul"; 
      ["LORE"] = "The filthy and dangerous beasts known as kergrim have fashioned a lair among the rocks below the cliffside fortress of Ashâgir. The Shagâni call this place Tûkurdul, the 'gnaw-heap,' and no other name could best it."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "20.91S"; 
          ["LONG"] = "71.78W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Urgudag"; 
      ["PROGRESS"] = "Find Urgudag"; 
      ["LORE"] = "There is beauty even in death, for at Urgudag flowers grow among the bone-piles assembled by the ravenous jackals of western Urash Dâr."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "21.75S"; 
          ["LONG"] = "68.49W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Khazâda"; 
      ["PROGRESS"] = "Find Khazâda"; 
      ["LORE"] = "The jackals of Khazâda have grown more bold in recent days, endangering the travellers who find they must travel in eastern Urash Dâr."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "24.56S"; 
          ["LONG"] = "58.15W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Khûn Sagaz"; 
      ["PROGRESS"] = "Find Khûn Sagaz"; 
      ["LORE"] = "The high canyon walls on either side of Khûn Sagaz ensure that any foolhardy enough to venture within have little hope of escaping the watchful gaze of the Orcs who dwell here."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "14.26S"; 
          ["LONG"] = "61.65W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Sar-kidul"; 
      ["PROGRESS"] = "Find Sar-kidul"; 
      ["LORE"] = "Deep within Sar-kidul, the Orcs have been kept busy fashioning great machines of war and training for the day they will be loosed upon the rest of the Ikorbân Valley."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "14.77S"; 
          ["LONG"] = "56.01W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Ab-dâna"; 
      ["PROGRESS"] = "Find Ab-dâna"; 
      ["LORE"] = "The encampment of Ab-dâna gives to the Orcs a view of much of the rest of Urash Dâr, providing a vantage point from which they can make their deadly plans for war."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "17.20S"; 
          ["LONG"] = "52.47W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Maurûsh"; 
      ["PROGRESS"] = "Find Maurûsh"; 
      ["LORE"] = "Orcs have overtaken the stone keep of Maurûsh and pushed out the former Ordâkhai residents. From this defensible position, the Orcs can strike almost any location in Urash Dâr with very little warning."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "25.74S"; 
          ["LONG"] = "62.81W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Dul Râkh"; 
      ["PROGRESS"] = "Find Dul Râkh"; 
      ["LORE"] = "Not content to remain within the dark cave where they were born, the scorpions of Dul Râkh boiled into the canyon outside. The scorpions overran the Orcs foolishly camped outside the cave mouth, and now the canyon belongs to them."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.11S"; 
          ["LONG"] = "57.44W"; 
        }; 
