      [10] = {
      ["NAME"] = "Zikrum-dûl"; 
      ["PROGRESS"] = "Find Zikrum-dûl"; 
      ["LORE"] = "This ancient hermitage was built into the walls of a narrow, spring-fed gap where greenery thrives despite the arid climate. It was once the retreat of poets and philosophers, but that was long ago; in the years since it held a trove of secret lore, generations of robbers and brigands have used it to store their own plunder."; 
      ["POINTS"] = {
        [1] = {
