  -- Imhûlar / Dangers in Shagâna
  [1879503578] = {
      [1] = {
      ["NAME"] = "Nisigurûm"; 
      ["PROGRESS"] = "Find Nisigurûm"; 
      ["LORE"] = "Nisigurûm, or the 'green-watch', was once part of a flourishing collection of human encampments in Nisigím, 'the emerald wood'. Now the name is tinged in sorrow, as the woods surrounding Nisigurûm have surrendered to the Pale Blight, and the corrupting influence of the Ordâkhai, who now control Nisigurûm. The Ordâkhai at Nisigurûm are themselves commanded by the Shâr of Ekhamât, the cruel Bârshud II."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "46.06S"; 
          ["LONG"] = "60.13W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Garash Kâru"; 
      ["PROGRESS"] = "Find Garash Kâru"; 
      ["LORE"] = "Providing the Ekhamâti a toehold into the fertile lands of Ambarûl, Garash Kâru sits on a commanding hilltop outside the southern Ambarûli marshes."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "28.00S"; 
          ["LONG"] = "82.00W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Garash Hûru"; 
      ["PROGRESS"] = "Find Garash Hûru"; 
      ["LORE"] = "The Ekhamâti have established crude fortifications and a rudimentary encampment outside a set of pits in northern Khûd Zagin. Few know what they are searching for there, and whether they should fear what they find."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "34.40S"; 
          ["LONG"] = "76.00W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Az Shûdai"; 
      ["PROGRESS"] = "Find Az Shûdai"; 
      ["LORE"] = "The high canyon walls form natural barriers and impediments to assault at Az Shûdai, providing an extra advantage to the Ordâkhai and Ekhamâti who dwell there."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "39.60S"; 
          ["LONG"] = "75.99W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Dun Shûma"; 
      ["PROGRESS"] = "Find Dun Shûma"; 
      ["LORE"] = "Dun Shûma, the King's Fortress, has long been rumoured to contain treasures of the Kings of Nisaka, an ancient dynasty of the Khûd. More recently, rumours suggest that artifacts of Aragín the Queller, famed ancient uniter of Shagâna and King of Hamât have spread, causing many to try their luck at finding these relics of the revered Aragín."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "44.88S"; 
          ["LONG"] = "83.83W"; 
        }; 
      }; 
      };
  };
