  -- Mûr Ghala / Reclaiming An Shêru
  [1879513775] = {
      [1] = {
      ["NAME"] = "Gadim-ûn"; 
      ["PROGRESS"] = "Find Gadim-ûn"; 
      ["LORE"] = "Gadim-ûn, or the Hallows of Gadim, is an ancient necropolis overlooking the White-wrath River from on high in the north-eastern reaches of An Shêru. The once desolate boneyard now serves as the hiding place of the Jatsakóri, escaped Shagâni thralls desperate to save their friends and family members from Ordâkhai bondage. In recent months, the corpses of Gadim-ûn have been awakened by some dark craft."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "50.75S"; 
          ["LONG"] = "67.23W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Jiret-menêsh"; 
      ["PROGRESS"] = "Find Jiret-menêsh"; 
      ["LORE"] = "An ancient hall of the Temámir dwarves, Jiret-menêsh has been home to dwarves since the First Age. At various points throughout history, they have been allied with the Kintai, Nêshak, Zajâna, and the Temámir of the Shoreward Stone in Umbar, among others. Following the razing of Lâkindar and the subsequent Din of Stone, Châmelek Gêta, Lord of Jiret-menêsh, ordered the closing of the doors, cutting Jiret-menêsh off from the outside world for the next one hundred years, only to re-open when the threats of the Ordâkhai and Barkhûshim have passed."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "52.57S"; 
          ["LONG"] = "76.80W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Khanâg Gur"; 
      ["PROGRESS"] = "Find Khanâg Gur"; 
      ["LORE"] = "Khanâg Gur is the last remaining khanâg still operating in An Shêru, though many merchants and travellers still don't consider it a safe place to rest. An outlaw gang called the Khanda-khêl, or 'the Laughing Ones', currently controls the khanâg. Their leader, or 'Mashár', is a man named Halshûm, who welcomes visitors as long as they spend coin during their stay. Those who do not spend enough coin often find themselves robbed on the road following their visit."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "56.87S"; 
          ["LONG"] = "71.88W"; 
        }; 
      }; 
      };
  };
  -- Mûr Ghala / Reclaiming Idagâl
  [1879513776] = {
      [1] = {
      ["NAME"] = "Ahâba"; 
      ["PROGRESS"] = "Find Ahâba"; 
      ["LORE"] = "Ahâba, or the 'well of the barrens', is a lush oasis and home of the Beltáni people. After decades of attempted subjugation by the Ordâkh Empire, the ancient people are slow to trust outsiders, but for those that earn that trust, it is a beautiful reprieve from the harsh conditions of Idagâl."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "55.23S"; 
          ["LONG"] = "82.39W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "The Dawn-warden"; 
      ["PROGRESS"] = "Find the Dawn-warden"; 
      ["LORE"] = "The Dawn-warden is a giant statue of the ancient hero-king of Nísaka, Izighûz Menûndari. Unlike its twin in Khûd Zagin, this statue is mostly intact. The advance troops of Aradûn have recently made it their camp in preparation for their invasion of Idagâl, to reclaim the region from the Ordâkhai. Unfortunately, they have learned too late that the statue is haunted by a mysterious force, known to the local people as Ishími, the Anguished Wind."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "49.34S"; 
          ["LONG"] = "95.95W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Nashûbu"; 
      ["PROGRESS"] = "Find Nashûbu"; 
      ["LORE"] = "Nashûbu is the secret camp of Shâra Mizâdi's forces in a hidden alcove at the base of the cliffs beneath Emax Dûl. Here, there is said to be a secret way to breach the defences the enemy city."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "65.47S"; 
          ["LONG"] = "87.24W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Dur Nâgu"; 
      ["PROGRESS"] = "Find Dur Nâgu"; 
      ["LORE"] = "Dur Nâgu, or the 'fortress of the island', is the ruins of an ancient Nêshakari fortress and ship-yard, where they once built river boats and launched them along the river Agâl. In recent days, it has become the secret haven of thralls escaping from the prison Esh Mêkag."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "57.35S"; 
          ["LONG"] = "88.64W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Hamâti Forward Camp"; 
      ["PROGRESS"] = "Find the Hamâti Forward Camp"; 
      ["LORE"] = "The Hamâti Forward Camp serves as Mizâdi's foothold into Idagâl, where she will eventually launch an attack on the fortress of Emax Dûl and push the Ordâkhai from Mûr Ghala."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "57.16S"; 
          ["LONG"] = "82.40W"; 
        }; 
      }; 
      };
  };
  -- Mûr Ghala / Tales of Idagâl
  [1879513777] = {
