  -- Mûr Ghala / Dangers in Kighân
  [1879513781] = {
      [1] = {
      ["NAME"] = "Shádhag"; 
      ["PROGRESS"] = "Find Shádhag"; 
      ["LORE"] = "The blight afflicting Adagím has taken root in Shádhag, just over the border in Kighân. Locals call it 'the Moulder-grove' as the plants begin to rot and decay in the once fertile grove. Strange and violent trees have taken over Shádhag and made it their own, striking at nearby Sormedân villagers in recent days."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "52.96S"; 
          ["LONG"] = "53.92W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Bâdrasag, the Blade-horn"; 
      ["PROGRESS"] = "Find Bâdrasag, the Blade-horn"; 
      ["LORE"] = "A pall hangs over the air of Bâdrasag, also known as the Blade-horn. Once a fortress to Second Age evils, the Blade-horn now sits empty. Locals stay well clear of it, whispering of strange spirits and haunting sounds that penetrate the night air outside its environs. What secrets could be hiding within, and what further evils might the Blade-horn be sheltering?"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.27S"; 
          ["LONG"] = "8.40W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Medân Makhai"; 
      ["PROGRESS"] = "Find Medân Makhai"; 
      ["LORE"] = "The bees of Medân Makhai once worked with the farmers of Sormedan. The farmers built them structures and kept them safe from predators and cold, and in return took a portion of the bees' honey. Recently, however, a new queen has caused the bees to become aggressive, unlike themselves, and they have savagely attacked and stung the farmers attempting to tend to them."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "53.57S"; 
          ["LONG"] = "55.91W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Dân Shatagan"; 
      ["PROGRESS"] = "Find Dân Shatagan"; 
      ["LORE"] = "The savage jázgai make their camp near the water hole of Dân Shatagan. Locals whisper of their savagery, and especially that of their matriarch and leader, whom they have named Bloodtooth."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "60.00S"; 
          ["LONG"] = "54.00W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Khatzâla"; 
      ["PROGRESS"] = "Find Khatzâla"; 
      ["LORE"] = "Khatzâla is the roost of the eccentric birds known as the kalorkhûn. The kalorkhûn can be quite aggressive when disturbed. Some have been domesticated and used as show animals, although only by the bravest and most adventurous of the Zajâni."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "61.60S"; 
          ["LONG"] = "51.00W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Jag Golód"; 
      ["PROGRESS"] = "Find Jag Golód"; 
      ["LORE"] = "A large encampment of Ordâkhai outside of Zajâna, this is where much of the military might of the Jewelled Council remains. Once the Blue Mutiny occurred, the Ordâkhai within the city were forced either within the Halls of Lajór within Zajâna, or outside of it and into Jag Golód. Here the Ordâkhai plot their next move, and attempt to retake Zajâna from their hated enemy, the Doorwards of Zajâna."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "65.20S"; 
          ["LONG"] = "52.40W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Hall of Lajór"; 
      ["PROGRESS"] = "Find the Hall of Lajór"; 
      ["LORE"] = "The former imperial palace of Zajâna, this is where Khastakhól of the Jewelled Council remains and holds court. The Jewelled Council, a shadow government of the empire of Ordâkh, once held sway over Zajâna but was recently overthrown by the people of Zajâna in the Blue Mutiny. Now the Jewelled Council controls only the Hall and its immediate surroundings. Although wounded, it is still a danger to strike out and reclaim all of Zajâna for Ordâkh."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "61.30S"; 
          ["LONG"] = "57.96W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Sâkhazai"; 
      ["PROGRESS"] = "Find Sâkhazai"; 
      ["LORE"] = "The lush grasslands of Kighân are the perfect environs for the graceful and swift oryx, who make the fields of Sâkhazai their home."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "58.00S"; 
          ["LONG"] = "57.60W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Jâr Obadal"; 
      ["PROGRESS"] = "Find Jâr Obadal"; 
      ["LORE"] = "The twisting and dark caves of Jâr Obadal have proven a welcome environment for cave spiders. In recent months Jâr Obadal has been claimed by Jûkhtar the Ravenous and her prodigious brood. They strike out at nearby patrols and unlucky travellers, bringing them back to the dark caves where they leash them with silk and twist them into ready meals."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "64.21S"; 
          ["LONG"] = "58.34W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Pazakhêra"; 
      ["PROGRESS"] = "Find Pazakhêra"; 
      ["LORE"] = "Located near the Great Road, Pazakhêra is home to many thieves, pick-pockets and rapscallions eager to feast on the riches of the merchant caravans travelling along the Great Road."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "57.20S"; 
          ["LONG"] = "60.00W"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "Hold of Jalkhíla"; 
      ["PROGRESS"] = "Find the Hold of Jalkhíla"; 
      ["LORE"] = "The Hold of Jalkhíla is where a group of hardened brigands make their camp. From here, they strike out at the nearby village of Sen Chatâk along with those travelling the Great Road on their way to or from Zajâna."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "51.33S"; 
          ["LONG"] = "63.60W"; 
        }; 
      }; 
      };
      [12] = {
      ["NAME"] = "Hurum Kâna"; 
      ["PROGRESS"] = "Find Hurum Kâna"; 
      ["LORE"] = "Hurum Kâna is fabled for its treasure caves, which many Zajâni claim possess huge treasure caches. However, none who enter Hurum Kâna have ever been seen again. Until recently, when a self-styled brigand king, Bârlat the Bold, has made Hurum Kâna his home. Travellers who escape with their lives claim to have seen Bârlat and his gang of brigands adorned with gold and gemstones of both weight and variety that can scarcely be believed."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "60.00S"; 
          ["LONG"] = "64.40W"; 
        }; 
      }; 
      };
      [13] = {
      ["NAME"] = "Glúkroz"; 
      ["PROGRESS"] = "Find Glúkroz"; 
      ["LORE"] = "Glúkroz was once a simple rock outcropping. Now goblins have made it their home, striking out at the nearby village of Sen Chatâk on vicious raids. The goblins are taking food, cleaving innocent villagers and setting fire to their homes."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "54.00S"; 
          ["LONG"] = "60.40W"; 
        }; 
      }; 
      };
      [14] = {
      ["NAME"] = "Charganpâta"; 
      ["PROGRESS"] = "Find Charganpâta"; 
      ["LORE"] = "The marshes of Charganpâta proved a fertile breeding ground for zizani, fierce biting insects of great size. For that reason, many steer well clear of Charganpâta and its belligerent insect inhabitants."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "50.93S"; 
          ["LONG"] = "60.53W"; 
        }; 
      }; 
      };
  };
  -- Mûr Ghala / Scouting Kighân
  [1879513782] = {
      [1] = {
      ["NAME"] = "Sormedân"; 
      ["PROGRESS"] = "Find Sormedân"; 
      ["LORE"] = "Sormedân means 'red soil' in the native Zajâni, so called for the village's red, clay-like soil. This soil has proven quite fertile, and results in Sormedân and its surrounds nurturing much of Kighân with its rich orchards and grain fields. The locals also keep cattle and bees, although there have been disturbances with both recently. The elders of Sormedân also keep a watchful eye on nearby Adagím. The sickness gripping Adagím has recently spilled over, and threatens to bespoil Sormedân's natural bounty."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "56.80S"; 
          ["LONG"] = "52.80W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Ingar-garâsh"; 
      ["PROGRESS"] = "Find Ingar-garâsh"; 
      ["LORE"] = "A modest-sized town, Ingar-garâsh has been abandoned in the battle between the Doorwards and the Jewelled Council over Zajâna. A large force of Ordâkhai loyal to the Jewelled Council are situated near Ingar-garâsh. Recently Shâra Mizâdi has established an encampment in Ingar-garâsh, and is striking out at the nearby Ordâkhai forces in her pursuit of the villainous Bârshud II."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "61.60S"; 
          ["LONG"] = "56.80W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Zajâna"; 
      ["PROGRESS"] = "Find the city of Zajâna"; 
      ["LORE"] = "The Jewel of Mûr Ghala, Zajâna is a city of trade and knowledge. Located at a fortuitous junction along the Great Road, Zajâna serves both Umbar and points further south, acting as a great connector. Zajâna was recently freed from the grip of the empire of Ordâkh, although the Jewelled Council loyal to Ordâkh still control a portion of Zajâna. The Doorwards have reestablished the rule of Zajâna by the Zajâni people following the Blue Mutiny, and rule over most of the city as a council of equals.\n\nTrade is in the air and culture of Zajâna, and traders far and wide come to the great city to ply their wares and make their fortunes. Elsewhere the Pohâni scholars work and research in the Kalmakhíla, the great library in Zajâna where much of the knowledge of Mûr Ghala is stored."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "62.40S"; 
          ["LONG"] = "62.40W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Sen Chatâk"; 
      ["PROGRESS"] = "Find Sen Chatâk"; 
      ["LORE"] = "A fertile fishing village, Sen Chatâk is located along the White-wrath river. A formerly peaceful village, Sen Chatâk has recently seen its troubled magnified with both brigand and goblin attacks, puncturing its once tranquil and friendly veneer."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "56.00S"; 
          ["LONG"] = "63.20W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Groves of Gatúr"; 
      ["PROGRESS"] = "Find the groves of Gatúr"; 
      ["LORE"] = "Orange groves that the locals of Sormedân keep and watch over. The groves do well in the clay soil of Sormedân, producing enough fruit that Sormedân farmers sell the excess both to Zajâna and other nearby towns."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "56.20S"; 
          ["LONG"] = "52.72W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Khamósh-engar"; 
      ["PROGRESS"] = "Find Khamósh-engar"; 
      ["LORE"] = "Khamósh-engar is where the locals of Sormedân bury their dead. Those buried here have their moments of death rendered in steles, carved stones which depict the moment and manner of their death."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "55.97S"; 
          ["LONG"] = "53.69W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Treasure Caves of Hurum Kâna"; 
      ["PROGRESS"] = "Find the treasure caves of Hurum Kâna"; 
      ["LORE"] = "A fabled set of caves located outside of Zajâna, fabulous wealth is rumoured to exist within the caves. Locals say a powerful curse is attached to those who enter the caves however, so few make their way inside. Recently an infamous brigand named Bârlat the Bold has made the caves his home, from which he strikes at merchants and travellers on the nearby Great Road."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "46.43N"; 
          ["LONG"] = "53.15E"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "The Court of Larinâsta"; 
      ["PROGRESS"] = "Find the Court of Larinâsta"; 
      ["LORE"] = "One of many markets within Zajâna, the Larinâsta is where many characters both savoury and unsavoury come to conduct their business. Much is bought and sold within the Larinâsta. Some of it is even legal."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "63.23S"; 
          ["LONG"] = "64.02W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "The Kalmakhíla"; 
      ["PROGRESS"] = "Find the Kalmakhíla"; 
      ["LORE"] = "The great library of Zajâna, the Kalmakhíla is a vast repository containing much of the knowledge gathered within Mûr Ghala."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "62.31S"; 
          ["LONG"] = "63.56W"; 
        }; 
      }; 
      };
  };
