  -- Mûr Ghala / New Threats in An Shêru
  [1879513789] = {
      [1] = {
      ["NAME"] = "Damudûr"; 
      ["PROGRESS"] = "Find Damudûr"; 
      ["LORE"] = "Near the head of the Usâl River, a rupture in the mountainside reveals the entrance to Damudûr, a First Age stronghold of the Thardúth. These caverns that once housed the breeding pits of the Utúgi have been hidden by sorcery since the time of Morgoth's defeat, and are now once again revealed. What dangers lie within, and what threats have already come forth?"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "60.60S"; 
          ["LONG"] = "71.09W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Naxar Dâl"; 
      ["PROGRESS"] = "Find Naxar Dâl"; 
      ["LORE"] = "Part of an ancient necropolis of Gadim-ûn, overlooking the White-wrath River. Many of the dead here have awakened from their graves in recent months, their rest disturbed by some dark sorcery."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "48.70S"; 
          ["LONG"] = "67.13W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Crypts of Khâb Daku"; 
      ["PROGRESS"] = "Find the Crypts of Khâb Daku"; 
      ["LORE"] = "A crypt only a short distance south of the ancient necropolis of Gadim-ûn, something has disturbed the dead, causing their decayed bodies to leave the tombs and wander the land."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "53.43S"; 
          ["LONG"] = "68.69W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Spoiler's Crag"; 
      ["PROGRESS"] = "Find Spoiler's Crag"; 
      ["LORE"] = "A hilltop in eastern An Shêru called Sang Luzûkh in Shagâni. It serves as the den for a large pack of jázgai, creatures known for scavenging, but who will attack if threatened or if food is scarce."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "54.16S"; 
          ["LONG"] = "66.60W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Zakhûr"; 
      ["PROGRESS"] = "Find Zakhûr"; 
      ["LORE"] = "Once a lush and verdant grove of the Kintai, this hilltop is now a refuge for bandits and other outlaws amidst a dry and rocky desert. The Elves are now gone, but several Veróthi, the trees that remain when an Elf has reached Trothúl, still linger."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "56.06S"; 
          ["LONG"] = "66.22W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Erakúndo, the Spent-lodes"; 
      ["PROGRESS"] = "Find the Spent-lodes"; 
      ["LORE"] = "An abandoned mine called Erakúndo by the Ordâkhi. It was last used in the time of Shurash Hûl, the emperor of Ordâkh, who led his armies north into Shagâna, destroying the Usâl River and much of the Mûr. This site is now home to feral mûmakil, beasts of burden who have survived or escaped the wars of Men."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "58.90S"; 
          ["LONG"] = "68.74W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Abníshu"; 
      ["PROGRESS"] = "Find Abníshu"; 
      ["LORE"] = "The roosting place of Kalorkhûn, terrifying birds of unusual size, who made their home at the height of the sky. Some say they taste like chicken."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "54.50S"; 
          ["LONG"] = "71.90W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "The Seething-wells"; 
      ["PROGRESS"] = "Find the Seething-wells"; 
      ["LORE"] = "Acidic hot springs in northern An Shêru, called Shêgarim by the locals, have boiled to the surface since the Din of Stone. While the water here can burn or kill most animals, rock-worms have found the superheated, acrid water to be to their liking."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "53.85S"; 
          ["LONG"] = "73.94W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Pools of Taridím"; 
      ["PROGRESS"] = "Find the Pools of Taridím"; 
      ["LORE"] = "Acidic hot springs in southern An Shêru that have boiled to the surface since the Din of Stone. While the water here can burn or kill most animals, rock-worms have found the superheated, acrid water to be to their liking."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "58.36S"; 
          ["LONG"] = "74.37W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Roost of the Anzûri"; 
      ["PROGRESS"] = "Find the Roost of the Anzûri"; 
      ["LORE"] = "This mountain-top at the height of the sky is home to a colony of rocs, called anzûri in Shagâna, giant birds that are as hostile as they are huge."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "50.13S"; 
          ["LONG"] = "72.95W"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "Onabóha"; 
      ["PROGRESS"] = "Find Onabóha"; 
      ["LORE"] = "An outpost of the Ordâkhai of Shêru, from here they dispatch patrols and attempt to maintain control of the western side of the region."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "55.98S"; 
          ["LONG"] = "76.95W"; 
        }; 
      }; 
      };
      [12] = {
      ["NAME"] = "The Beast-fields"; 
      ["PROGRESS"] = "Find the Beast-fields"; 
      ["LORE"] = "Called Modan Rôkh in Ordâkhai, the Beast-fields are named for the sûlokil you will usually find there."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "59.22S"; 
          ["LONG"] = "77.63W"; 
        }; 
      }; 
      };
      [13] = {
      ["NAME"] = "Uruthúsh"; 
      ["PROGRESS"] = "Find Uruthúsh"; 
      ["LORE"] = "One must be either very brave or very foolish to enter Uruthúsh, as it is home to a band of fearsome Utûgi, Orcs given life in the Elder Days by Morgoth's dark craft."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "61.85S"; 
          ["LONG"] = "76.79W"; 
        }; 
      }; 
      };
      [14] = {
      ["NAME"] = "Arch of Adazâr"; 
      ["PROGRESS"] = "Find the Arch of Adazâr"; 
      ["LORE"] = "This arching bridge is all that remains of these long-forgotten ruins in western An Shêru. It is now home to a band of kergrim who scavenge the remains of the victims of this harsh environment."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "59.11S"; 
          ["LONG"] = "79.10W"; 
        }; 
      }; 
      };
      [15] = {
      ["NAME"] = "Slopes of Shâlahin"; 
      ["PROGRESS"] = "Find the Slopes of Shâlahin"; 
      ["LORE"] = "Gredbyg have lived on these rocky slopes as long as anyone can remember. Some say they have been here since before the land was ravaged and An Shêru was still green and forested."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "53.96S"; 
          ["LONG"] = "78.92W"; 
        }; 
      }; 
      };
      [16] = {
      ["NAME"] = "Gebarakór"; 
      ["PROGRESS"] = "Find Gebarakór"; 
      ["LORE"] = "Instead of skilfully mining into the mountain, the Ordâkhai have their enthralled Jatsakóri workers excavating an open pit, forever scarring the land. This practice is detested by the Temámir of Shêru, and was banned when the Men of Nísaka swore the peace-bringing Oath of Jiret-menêsh, in which several mines in An Shêru were surrendered to Men so long as they swore ever to honour and respect the land from which they took their bounty, and never to cut stone except with the greatest care."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "58.17S"; 
          ["LONG"] = "70.29W"; 
        }; 
      }; 
      };
      [17] = {
      ["NAME"] = "Kôth Rau"; 
      ["PROGRESS"] = "Find Kôth Rau"; 
      ["LORE"] = "Kôth Rau, the centre of Ordâkhai activity in An Shêru, is situated on a slope and encompasses the entrance to Damudûr. Taking orders from a coven of Bokhóri sorceresses, the soldiers here are zealots who deny the defeat of Barkhûsh and await his return. There is also an Utûgi presence in the camp, as well as prisoners who are taken and questioned for unknown reasons."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "59.51S"; 
          ["LONG"] = "72.38W"; 
        }; 
      }; 
      };
      [18] = {
      ["NAME"] = "Lâkindar"; 
      ["PROGRESS"] = "Find Lâkindar"; 
      ["LORE"] = "In the days of old, Lâkindar was a prosperous mine of the Temámir dwarves. Now, however, it is commonly called 'The Quelling-house' due to its more recent use by the invading armies of Ordâkh. After brutally stamping out resistance in An Shêru, the mine was used as an execution chamber and dumping ground for the bodies of dissenters. It is also said that the Priests of Barkhûsh ritually sacrificed many an innocent dwarf in this unhappy place, adding to its unnerving reputation. To make matters worse, in recent months, the corpses of The Quelling-house have been awakened by some dark craft."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "62.98S"; 
          ["LONG"] = "78.99W"; 
        }; 
      }; 
      };
  };
  -- Mûr Ghala / Scouting Adagím
  [1879513790] = {
      [1] = {
      ["NAME"] = "Sul Madásh"; 
      ["PROGRESS"] = "Find Sul Madásh"; 
      ["LORE"] = "The dale of beauty as it is known in the native Kintár. Sul Madásh is the chief grove-settlement of Adagím. A green sanctuary overlooking the devastation, tucked among cascading streams within a fold of the eastern Mûr, but the infection can only be contained for so long while the Elves' numbers continue to decline.\n\nThe chieftains of Sul Madásh, a wedded pair – Ildimár the husband, Dáthlil the wife – have thus far kept the Pale Blight at bay but know the battle will soon be lost. Defiant to the end, they intend to go down fighting."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "46.31S"; 
          ["LONG"] = "35.72W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Laivárth"; 
      ["PROGRESS"] = "Find Laivárth"; 
      ["LORE"] = "A Kinta grove, hitherto unspoiled, that has begun to succumb to the Pale Blight. The tender of the grove, a hermit named Tálbiral, has razed the forest around the grove in an attempt to form a barrier from the rot."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "39.30S"; 
          ["LONG"] = "46.34W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Sâr Marsag"; 
      ["PROGRESS"] = "Find Sâr Marsag"; 
      ["LORE"] = "Sâr Marsag, the last camp on the road into Kighân, is held by the scouts of Adagím as a bastion within the rotting forest. They keep their bonfire burning to provide a beacon to travellers that they will be safe here as the battle against the Pale Blight rages on."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "48.13S"; 
          ["LONG"] = "45.08W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "The Folly of Nagakhêdi"; 
      ["PROGRESS"] = "Find the Folly of Nagakhêdi"; 
      ["LORE"] = "An ancient wonder from before the Din of Stone carved into the mountainside in Adagím. The structure was being built by a ruler who wanted to make his mark on this world known as Nagakhêdi. The wonder was left unfinished and sealed off long ago.\n\nThe Kintai of the woods have left the structure untouched for years as they saw it as a futile effort from the start even now calling it the 'Fool's Descent', and their eyes have been turned towards safeguarding their groves against the blight that rages in their lands. The sealed door has cracks in its stone and a foul air leaks out from within."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "52.73S"; 
          ["LONG"] = "33.59W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Tûl Ama"; 
      ["PROGRESS"] = "Find Tûl Ama"; 
      ["LORE"] = "Tûl Ama, known as the Hill of the Mother, is an outcropping where once grew a giant holm-oak, one of the oldest in Shagâna, called the Old Mother in tale and song. It is now dying, the fungal rot rising up its massive trunk and causing it to weep bloody sap as its leaves blacken and wither.\n\nThe hill's warden, Irsinith, has communed with the tree for centuries and speaks on her behalf, though the tree's affliction has left her sickly and wracked with grief."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "40.70S"; 
          ["LONG"] = "41.31W"; 
        }; 
      }; 
      };
  };
