  -- Mûr Ghala / New Threats in Idagâl
  [1879513793] = {
      [1] = {
      ["NAME"] = "The Haunt of Kidu-bâla"; 
      ["PROGRESS"] = "Find the Haunt of Kidu-bâla"; 
      ["LORE"] = "Kidu-bâla, or 'rebel-covert', is a cliff-side camp of brigands and Ordâkhai deserters who have declared independence from the laws of both the empire and any upstart kingdoms who claim dominion over Idagâl. They prey on desperate travellers and steal the meager resources the local Beltáni people have."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "10.48S"; 
          ["LONG"] = "39.25W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Duríga"; 
      ["PROGRESS"] = "Find Duríga"; 
      ["LORE"] = "The brigands at Duríga, or 'gleaners' cleft', survive by assaulting Ordâkhai patrols and stealing the rations from the escaped thralls hiding in the ruins of Dur Nâgu."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "60.89S"; 
          ["LONG"] = "88.19W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Fane of Shahûru"; 
      ["PROGRESS"] = "Find the Fane of Shahûru"; 
      ["LORE"] = "Shahûru, or 'shrine on a summit', is all that remains of an ancient Nêshak temple where the local people left offerings, praying for abundant harvests and the blessings of rain. The identity of the being the Mûr folk prayed to is lost to time, but indications are that they were female."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "51.99S"; 
          ["LONG"] = "82.42W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Gnasher's Delf"; 
      ["PROGRESS"] = "Find Gnasher's Delf"; 
      ["LORE"] = "Gnasher's Delf, or 'Haraz Hûr', is just the top of a large grodbog hive. They thrive in the cliffs because of deep cracks in the rock that lead to ground water, opened by the Din of Stone over a hundred years ago."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "44.10S"; 
          ["LONG"] = "94.17W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Nax Shalâl"; 
      ["PROGRESS"] = "Find Nax Shalâl"; 
      ["LORE"] = "Nax Shalâl, or 'the Slithering Pit', is a recessed oasis, hidden in the cliffs. What would be a refuge for the people of Idagâl has become too dangerous to go near, as the local cobra population has exploded in size."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "53.63S"; 
          ["LONG"] = "95.38W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Ushumût"; 
      ["PROGRESS"] = "Find Ushumût"; 
      ["LORE"] = "Ushumût, or the Grave of Serpents, is the remains of three massive dragons and home to the wild-drakes of Idagâl. The Beltáni have passed down the tale of the fall of these dragons, named Ahûshu, Nuzêru, and Rabûg. They say that Shurug-nîn, the mythical hero of the First Age, struck them down, and their bodies fell into the lake where they rested for many thousands of years. It was only relatively recently that the Din of Stone drained the lake and revealed the dragons' grave to the world."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "53.59S"; 
          ["LONG"] = "88.81W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "The Wither-watch"; 
      ["PROGRESS"] = "Find the Wither-watch"; 
      ["LORE"] = "The Wither-watch, or Okhatohól, was once a thriving Shagâni town overlooking the river Agâl. The Din of Stone, the drying of the lake, and the invasion by the Ordâkhai slowly left the town nearly abandoned, as people fled for a better life. In recent years, the Ordâkhai have completely taken over the town, to use it as a northern base to launch raids. The few remaining residents were taken and never seen again."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "50.51S"; 
          ["LONG"] = "86.17W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Jolakhúro"; 
      ["PROGRESS"] = "Find Jolakhúro"; 
      ["LORE"] = "Jolakhúro, or 'notch of the tunnel', is the Ordâkhai forward camp that watches the road to their main fortress at Emax Dûl. The soldiers there watch for approaching enemies, and are the first sent out in response to trouble elsewhere in Idagâl."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "62.97S"; 
          ["LONG"] = "83.26W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Emax Dûl"; 
      ["PROGRESS"] = "Find Emax Dûl"; 
      ["LORE"] = "Emax Dûl, 'high hall of the cleft', or the High-hold, is an ancient fortress that has stood through the rise and fall of the many dynasties of both Nêshak and Nísaka. It is now the seat of power of the Ordâkhai in Mûr Ghala, and home to the royal family of the crown prince of the empire."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "65.41S"; 
          ["LONG"] = "88.70W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Karmu Râx"; 
      ["PROGRESS"] = "Find Karmu Râx"; 
      ["LORE"] = "Karmu Râx, or 'the mound of the turtles', is the gathering place for many dread-tortoises along the trickle that remains of the river Agâl. The shallow water and shelter provided by old wrecks from ships beached by the Din of Stone prove a suitable environment for the reptiles."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "56.81S"; 
          ["LONG"] = "85.56W"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "The Scardelve"; 
      ["PROGRESS"] = "Find the Scardelve"; 
      ["LORE"] = "The Scardelve, or 'Góbor-noti', is the remains of an old pit mine carved from the cliff by the Ordâkhai. Once the ore ran dry, it became a holding pen for Mûmakil. As the Ordâkhai began to lose control of the region following their loss at the Battle of Pelennor Fields, they too lost control of the mûmakil housed in the mine. The great beasts now run wild across all of Idagâl."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "58.78S"; 
          ["LONG"] = "82.61W"; 
        }; 
      }; 
      };
      [12] = {
      ["NAME"] = "Tombs of Khâb Ishil"; 
      ["PROGRESS"] = "Find the Tombs of Khâb Ishil"; 
      ["LORE"] = "Khâb Ishil, or 'the tomb of shards', is the ancient burial house of heroes from the kingdoms of Nêshak and Nísaka. It was long ago sealed and left untouched for hundreds of years. The Din of Stone shook the earth and opened the tomb, allowing the kergrim to enter, defile it, and make it their nest."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "49.89S"; 
          ["LONG"] = "91.13W"; 
        }; 
      }; 
      };
      [13] = {
      ["NAME"] = "Esh Mêkag Pit-mine"; 
      ["PROGRESS"] = "Find Esh Mêkag"; 
      ["LORE"] = "Esh Mêkag, 'the Silent Mouth', is an ancient Nêshakari fortress built into the stone cliffs of the Mûr. In recent years, the Ordâkhai have turned the fortress into a horrific prison and work-camp. The priests of Barkhûsh oversee the subjugation of people from all over Shagâna, who become thralls to the empire."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "60.01S"; 
          ["LONG"] = "90.90W"; 
        }; 
      }; 
      };
  };
